INSERT INTO `chat_history` VALUES (8, 'Chào bạn, ngoài mẫu túi cá sấu, cửa hàng Thu Ngân bên mình còn có một số mẫu ba lô vải sáp rất bền đẹp và phong cách, mời bạn tham khảo nhé:\n\n1. **Ba lô vải bạt Mugwort (Mã 426):** Giá 3.596.000đ.\n2. **Ba lô vải bạt Mugwort (Mã 1290):** Giá 4.163.750đ.\n3. **Ba lô Blackberry vải sáp (Mã 298):** Giá 5.079.500đ.\n\nCác mẫu ba lô này đều được làm từ vải sáp hạng nặng, có khả năng chống thấm nước, ngăn đựng laptop 15 inch và thiết kế rất tinh tế với phần cứng bằng đồng cổ.\n\nMời bạn xem hình ảnh các sản phẩm bên dưới nhé:', '2026-07-09 09:50:42.000000', '[{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"},{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"298\",\"url\":\"https://i.etsystatic.com/65382565/r/il/0a3684/8166628609/il_510x680.8166628609_7zxo.jpg\"}]', 'assistant', '633bae1e-73bf-4bdc-b4d1-bfe59acef567', 'user-1766022973', NULL, NULL);
INSERT INTO `chat_history` VALUES (9, 'thông tin của balo mã 426', '2026-07-09 09:53:05.000000', NULL, 'user', '633bae1e-73bf-4bdc-b4d1-bfe59acef567', 'user-1766022973', NULL, NULL);
INSERT INTO `chat_history` VALUES (10, 'Chào bạn, rất vui được chia sẻ thông tin chi tiết về chiếc ba lô vải bạt Mugwort (mã 426) mà bạn đang quan tâm ạ:\n\n*   **Tên sản phẩm:** Ba lô vải bạt Mugwort\n*   **Mã sản phẩm:** 426\n*   **Giá bán:** 3.596.000đ\n*   **Chất liệu:** Vải sáp hạng nặng kết hợp với viền da ngải cứu cao cấp.\n*   **Đặc điểm nổi bật:**\n    *   Khả năng chống thấm nước cực tốt ở bên ngoài.\n    *   Có ngăn đựng máy tính xách tay (laptop) có đệm, vừa vặn cho các dòng máy 15 inch.\n    *   Thiết kế tiện lợi với nhiều túi nhỏ cả bên trong và bên ngoài.\n    *   Phần cứng (khóa, móc) được làm bằng đồng cổ tạo vẻ sang trọng, bền bỉ.\n*   **Dung tích:** 20L, rất phù hợp để đi học, đi làm hoặc những chuyến đi ngắn ngày.\n\nĐây là một mẫu ba lô rất bền và có phong cách cổ điển, tinh tế. Mời bạn xem hình ảnh của sản phẩm bên dưới nhé!', '2026-07-09 09:53:09.000000', '[{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"},{\"product_id\":\"906\",\"url\":\"https://i.etsystatic.com/22277583/r/il/855893/5108784898/il_510x680.5108784898_du77.jpg\"},{\"product_id\":\"42\",\"url\":\"https://i.etsystatic.com/63906229/r/il/efc4e1/7920835866/il_1588xN.7920835866_p4q8.jpg\"}]', 'assistant', '633bae1e-73bf-4bdc-b4d1-bfe59acef567', 'user-1766022973', NULL, NULL);
INSERT INTO `chat_history` VALUES (11, 'thời tiết hôm nay thế nào', '2026-07-09 09:55:55.000000', NULL, 'user', 'fe7e8b5b-5b32-4705-900e-d7353ec1b2a9', 'user-1766022973', NULL, NULL);
INSERT INTO `chat_history` VALUES (12, 'Chào bạn, rất xin lỗi vì mình là trợ lý ảo chuyên tư vấn các sản phẩm tại cửa hàng Thu Ngân nên mình không có thông tin cập nhật về thời tiết bên ngoài ạ.\n\nTuy nhiên, nếu bạn đang tìm kiếm một món đồ để làm mới không gian sống hoặc một chiếc áo thoải mái cho ngày hôm nay, mình có một vài gợi ý rất thú vị từ cửa hàng:\n\n1. **Mỹ thuật Heather Nature Ảnh In**: Một bức tranh thiên nhiên tinh tế, in trên giấy cotton cao cấp, rất phù hợp để trang trí nhà cửa.\n2. **Áo thun Vintage 1992 “Temple Tornado”**: Mẫu áo này hiện đang được giảm giá 30% và có rất nhiều màu sắc cũng như kích thước để bạn lựa chọn đấy ạ.\n\nBạn có muốn mình tư vấn kỹ hơn về sản phẩm nào không?', '2026-07-09 09:55:59.000000', '[{\"product_id\":\"77\",\"url\":\"https://i.etsystatic.com/63125473/r/il/1372af/8016911479/il_1588xN.8016911479_8coj.jpg\"},{\"product_id\":\"1805\",\"url\":\"https://i.etsystatic.com/9487154/c/1700/1700/399/166/il/e14cc6/4280898027/il_510x680.4280898027_oqj8.jpg\"},{\"product_id\":\"6\",\"url\":\"https://i.etsystatic.com/36589265/r/il/aa730c/5037981985/il_fullxfull.5037981985_s15b.jpg\"}]', 'assistant', 'fe7e8b5b-5b32-4705-900e-d7353ec1b2a9', 'user-1766022973', NULL, NULL);
INSERT INTO `chat_history` VALUES (13, 'áo thun vintage 1992', '2026-07-09 09:56:42.000000', NULL, 'user', 'fe7e8b5b-5b32-4705-900e-d7353ec1b2a9', 'user-1766022973', NULL, NULL);
