INSERT INTO `chat_history` VALUES (16, 'Dạ, mời bạn xem hình ảnh của chiếc áo thun Vintage 1992 “Temple Tornado” ngay bên dưới nhé!\n\nMẫu áo này có chất liệu vải rất thoáng mát và thiết kế cổ điển cực kỳ dễ phối đồ. Bạn thấy mẫu này có phù hợp với phong cách của mình không ạ? Nếu bạn cần tư vấn thêm về bảng size để chọn được chiếc áo vừa vặn nhất, cứ cho mình biết nhé!', '2026-07-09 09:56:55.000000', '[]', 'assistant', 'fe7e8b5b-5b32-4705-900e-d7353ec1b2a9', 'user-1766022973', NULL, NULL);
