INSERT INTO `chat_history` VALUES (28, 'Chào bạn, đây là thông tin chi tiết về sản phẩm **Xà phòng nghệ nhân Twilight Artisan sữa dê (Mã 1966)** tại cửa hàng Thu Ngân để bạn tham khảo nhé:\n\n*   **Tên sản phẩm:** Xà phòng nghệ nhân Twilight Artisan sữa dê\n*   **Mã sản phẩm:** 1966\n*   **Danh mục:** Tắm & làm đẹp\n*   **Giá bán:** 253,500đ\n*   **Đánh giá:** 5.0/5 sao.\n*   **Mô tả:** Đây là loại xà phòng sữa dê bổ dưỡng, mang hương thơm hoàng hôn dịu nhẹ cùng các thành phần thực vật lành tính. Sản phẩm được sản xuất bằng phương pháp xử lý lạnh để bảo quản glycerin tự nhiên, cam kết không chứa sunfat, paraben và màu nhân tạo. Mỗi thanh có trọng lượng 4,5oz.\n\nĐây là lựa chọn tuyệt vời nếu bạn đang tìm kiếm sản phẩm chăm sóc da tự nhiên và an toàn. Mời bạn xem hình ảnh của sản phẩm bên dưới nhé!', '2026-07-09 10:01:13.000000', '[{\"product_id\":\"1966\",\"url\":\"https://i.etsystatic.com/9971299/r/il/a63c01/1577402102/il_1588xN.1577402102_563v.jpg\"}]', 'assistant', '89f993f9-5f95-4a51-bb59-972f7be272a1', 'user-1766022973', NULL, NULL);
