INSERT INTO `chat_history` VALUES (36, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTại cửa hàng Thu Ngân hiện đang có mẫu \"Kệ Gỗ Aurora Chạm Khắc Bằng Tay\" rất sang trọng và tinh tế. Sản phẩm này được làm từ gỗ óc chó nguyên khối, hoàn thiện bằng dầu sáp ong an toàn và có thiết kế cạnh cực quang độc đáo.\n\nHiện tại cửa hàng đang có 3 phiên bản với mức giá khác nhau để bạn lựa chọn:\n1. **Mã 1155:** Giá 3,271,000đ.\n2. **Mã 291:** Giá 3,410,250đ.\n3. **Mã 2019:** Giá 3,487,750đ (đã có 1 sản phẩm được bán ra).\n\nTất cả các mẫu đều có cùng kích thước (dài 24 inch, sâu 6 inch) và bao gồm đầy đủ phụ kiện lắp đặt. Mời bạn xem hình ảnh của sản phẩm bên dưới nhé:', '2026-07-09 10:16:13.000000', '[{\"product_id\":\"291\",\"url\":\"https://i.etsystatic.com/65228819/r/il/16fd6b/8190016837/il_510x680.8190016837_5vfq.jpg\"},{\"product_id\":\"2019\",\"url\":\"https://i.etsystatic.com/58686080/r/il/58ce88/7278616766/il_1588xN.7278616766_dmln.jpg\"},{\"product_id\":\"1155\",\"url\":\"https://i.etsystatic.com/66490104/r/il/8bed8d/8202670889/il_510x680.8202670889_agmx.jpg\"}]', 'assistant', '6ee5f989-20dd-4240-95c4-766fe36fab1c', 'user-1766022973', NULL, NULL);
