INSERT INTO `chat_history` VALUES (48, 'Chào bạn, rất vui được hỗ trợ bạn thêm thông tin về sản phẩm này!\n\nKệ Gỗ Aurora mã 1155 là một lựa chọn tuyệt vời tại cửa hàng Thu Ngân với thiết kế tinh tế. Dưới đây là thông tin chi tiết để bạn tham khảo:\n\n*   **Tên sản phẩm:** Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã 1155).\n*   **Chất liệu:** Gỗ óc chó nguyên khối, được hoàn thiện bằng dầu sáp ong an toàn thực phẩm.\n*   **Đặc điểm nổi bật:** Kệ nổi được chạm khắc thủ công tỉ mỉ với chi tiết cạnh cực quang độc đáo, mang lại vẻ đẹp sang trọng cho không gian sống.\n*   **Kích thước:** Chiều dài 24 inch, độ sâu 6 inch.\n*   **Phụ kiện:** Sản phẩm đã bao gồm đầy đủ phần cứng để bạn lắp đặt dễ dàng.\n*   **Giá bán:** 3,271,000đ.\n*   **Đánh giá:** Sản phẩm hiện có đánh giá 5.0/5 sao.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần hỗ trợ đặt hàng hoặc có thêm câu hỏi nào khác, đừng ngần ngại nhắn cho em nha.', '2026-07-09 10:44:40.000000', '[{\"product_id\":\"1155\",\"url\":\"https://i.etsystatic.com/66490104/r/il/8bed8d/8202670889/il_510x680.8202670889_agmx.jpg\"},{\"product_id\":\"1251\",\"url\":\"https://i.etsystatic.com/26281722/c/1003/1003/0/179/il/3db4d5/7776926597/il_510x680.7776926597_13lw.jpg\"},{\"product_id\":\"1795\",\"url\":\"https://i.etsystatic.com/47402380/r/il/e298f6/7446291668/il_510x680.7446291668_8kko.jpg\"}]', 'assistant', '97cdd4d5-8368-4c36-b882-5864e7a58e33', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (49, 'thông tin sản phẩm 100', '2026-07-09 10:44:52.000000', NULL, 'user', '97cdd4d5-8368-4c36-b882-5864e7a58e33', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (50, 'Chào bạn, rất vui được hỗ trợ bạn thông tin về sản phẩm này!\n\nSản phẩm mã 100 tại cửa hàng Thu Ngân là một chiếc thớt gỗ cao cấp với thông tin chi tiết như sau:\n\n*   **Tên sản phẩm:** Thớt quả óc chó Yarrow cuối hạt.\n*   **Chất liệu:** Được làm thủ công từ gỗ quả óc chó Yarrow và gỗ cây phong, bề mặt thớt được bôi dầu khoáng an toàn thực phẩm, rất nhẹ nhàng và bảo vệ lưỡi dao của bạn.\n*   **Đặc điểm nổi bật:** Thiết kế thớ cuối (end-grain) bền bỉ, có rãnh thoát nước ép ở một bên rất tiện lợi khi chế biến thực phẩm.\n*   **Kích thước:** 12\" x 9\" x 1,5\".\n*   **Giá bán:** 3,783,000đ.\n*   **Đánh giá:** Sản phẩm hiện có đánh giá 5.0/5 sao.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần hỗ trợ đặt hàng hoặc có thêm câu hỏi nào khác, đừng ngần ngại nhắn cho em nha.', '2026-07-09 10:44:53.000000', '[{\"product_id\":\"100\",\"url\":\"https://i.etsystatic.com/49024289/r/il/01403b/7806820117/il_1588xN.7806820117_9oq3.jpg\"},{\"product_id\":\"100\",\"url\":\"https://i.etsystatic.com/49024289/r/il/03eb28/7758871140/il_1588xN.7758871140_qffi.jpg\"},{\"product_id\":\"100\",\"url\":\"https://i.etsystatic.com/49024289/r/il/d23c53/7453814572/il_1588xN.7453814572_t35d.jpg\"}]', 'assistant', '97cdd4d5-8368-4c36-b882-5864e7a58e33', 'user-1766022973', b'1', NULL);
