INSERT INTO `chat_history` VALUES (56, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTại cửa hàng Thu Ngân, sản phẩm có mã 119 là \"Vòng cổ Medlar theo phong cách cổ điển\". Đây là một món trang sức tinh tế với mặt dây chuyền bằng đồng thau được chạm khắc tỉ mỉ, có thể mở ra để chứa hai bức ảnh nhỏ bên trong. Sản phẩm đi kèm với dây chuyền đồng thau dài 24 inch và một túi nhung sang trọng, có giá là 2,623,750đ.\n\nMời bạn xem hình ảnh của sản phẩm bên dưới nhé!', '2026-07-09 10:47:42.000000', '[{\"product_id\":\"119\",\"url\":\"https://i.etsystatic.com/23983087/r/il/5be40b/7797021103/il_1588xN.7797021103_au2a.jpg\"},{\"product_id\":\"119\",\"url\":\"https://i.etsystatic.com/23983087/r/il/116771/7797021179/il_1588xN.7797021179_lsdq.jpg\"},{\"product_id\":\"119\",\"url\":\"https://i.etsystatic.com/23983087/r/il/0f403d/7797021177/il_1588xN.7797021177_may8.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'1', NULL);
