INSERT INTO `chat_history` VALUES (60, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nRất tiếc, hiện tại cửa hàng Thu Ngân của chúng mình chưa có sản phẩm nào thuộc danh mục tranh ảnh. Hiện tại, cửa hàng đang tập trung vào các sản phẩm như túi xách, quần áo, trang sức và đồ nội thất gỗ.\n\nHy vọng bạn có thể tìm thấy một món đồ khác ưng ý tại cửa hàng của chúng mình nhé! Nếu bạn cần tư vấn thêm về các sản phẩm hiện có, đừng ngần ngại cho mình biết nha.', '2026-07-09 10:52:19.000000', '[]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
