INSERT INTO `chat_history` VALUES (62, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTại cửa hàng Thu Ngân, chúng mình hiện có một số mẫu thiệp cưới thiết kế thủ công rất tinh tế thuộc danh mục Giấy & tiệc. Các mẫu thiệp đều được in trên giấy bìa tái chế chất lượng cao (130lb), kích thước A2 và đi kèm phong bì kraft tái chế. Bạn có thể tham khảo các lựa chọn sau:\n\n1. **Thiệp cưới màu nước chạng vạng (Mã 1426):** Thiết kế với hình minh họa thực vật chạng vạng, giá 166,500đ.\n2. **Thiệp cưới màu nước Dogwood (Mã 146):** Thiết kế với hình minh họa thực vật cây dương đào, giá 217,000đ.\n3. **Thiệp cưới màu nước Yarrow (Mã 1234):** Thiết kế với hình minh họa thực vật cỏ thi, giá 315,000đ.\n\nCác mẫu này đều có sẵn tùy chọn bộ 1, 5 hoặc 10 thiệp để bạn lựa chọn theo nhu cầu. Mời bạn xem các hình ảnh của sản phẩm bên dưới nhé!', '2026-07-09 10:52:34.000000', '[{\"product_id\":\"1426\",\"url\":\"https://i.etsystatic.com/7241941/r/il/fa132a/7600819492/il_510x680.7600819492_b8tx.jpg\"},{\"product_id\":\"1234\",\"url\":\"https://i.etsystatic.com/64956330/r/il/0ef54e/8044880767/il_510x680.8044880767_7ttm.jpg\"},{\"product_id\":\"146\",\"url\":\"https://i.etsystatic.com/10967690/r/il/0d6cd8/3714646985/il_1588xN.3714646985_dar4.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (63, 'tranh treo tường', '2026-07-09 10:52:41.000000', NULL, 'user', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (64, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTại cửa hàng Thu Ngân, chúng mình có sản phẩm \"Tranh treo tường Macramé Riverstone\" (mã 673) rất phù hợp với nhu cầu của bạn. Đây là một tác phẩm nghệ thuật treo tường được thắt nút thủ công tinh xảo từ dây bông tự nhiên, kết hợp với các chi tiết đá ven sông và chốt gỗ lũa độc đáo. Sản phẩm có thiết kế nhiều lớp tua rua cùng các họa tiết hình học bắt mắt, kích thước 20\"W x 40\"L, mang lại vẻ đẹp mộc mạc và sang trọng cho không gian sống. Sản phẩm hiện có giá là 2,502,500đ.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé!', '2026-07-09 10:52:42.000000', '[{\"product_id\":\"673\",\"url\":\"https://i.etsystatic.com/26714463/r/il/0ca449/6027248954/il_510x638.6027248954_3r3u.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'1', NULL);
INSERT INTO `chat_history` VALUES (65, 'giới thiệu sản phẩm khác', '2026-07-09 10:52:56.000000', NULL, 'user', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (66, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTại cửa hàng Thu Ngân, mình xin giới thiệu đến bạn một số mẫu nhẫn trang sức độc đáo đang có sẵn:\n\n1. **Nhẫn tuyên bố quả việt quất pha lê thô (Mã 1310):** Một chiếc nhẫn táo bạo được làm từ đồng thau tái chế với điểm nhấn là pha lê việt quất thô. Dây đeo có thể điều chỉnh linh hoạt từ size 6 đến 9. Mỗi tinh thể đều là duy nhất về hình dạng và màu sắc, được hoàn thiện với lớp patina cây nham lê tinh tế. Sản phẩm có giá 913,250đ.\n\n2. **Vòng tuyên bố Mugwort pha lê thô (Mã 1182):** Chiếc nhẫn nổi bật với pha lê ngải cứu thô trên nền đồng thau tái chế. Sản phẩm có thể điều chỉnh kích cỡ từ 6-9, mang vẻ đẹp tự nhiên và độc bản. Sản phẩm có giá 1,496,500đ.\n\n3. **Vòng tuyên bố Mugwort pha lê thô (Mã 318):** Đây cũng là mẫu nhẫn ngải cứu với thiết kế tương tự mã 1182 nhưng có mức giá ưu đãi hơn là 1,074,500đ.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé!', '2026-07-09 10:52:59.000000', '[{\"product_id\":\"1310\",\"url\":\"https://i.etsystatic.com/59957673/c/1530/1530/394/629/il/617848/8021928688/il_510x680.8021928688_qpcn.jpg\"},{\"product_id\":\"1182\",\"url\":\"https://i.etsystatic.com/59957673/c/2008/2008/0/538/il/88e932/7916772458/il_510x680.7916772458_jo72.jpg\"},{\"product_id\":\"318\",\"url\":\"https://i.etsystatic.com/13316288/r/il/4391c7/5217611006/il_510x638.5217611006_hejv.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (67, 'còn mẫu khác không', '2026-07-09 10:53:06.000000', NULL, 'user', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (68, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTại cửa hàng Thu Ngân, ngoài các sản phẩm đã giới thiệu, mình xin gợi ý thêm cho bạn một số lựa chọn khác thuộc các danh mục đa dạng như sau:\n\n1. **Mỹ thuật Heather Nature Ảnh In (Mã 1805):** Nếu bạn yêu thích nghệ thuật, đây là bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây thạch nam. Sản phẩm được in trên giấy cotton 100% với mực màu cao cấp, có khả năng chống phai màu lên đến hơn 100 năm. Sản phẩm có giá 813,750đ và có sẵn nhiều kích thước từ 5x7 đến 16x20.\n\n2. **Áo \"Ăn cơm chưa\" (Mã 2030):** Một chiếc áo thun độc đáo với dòng chữ \"ăn cơm chưa\" đầy gần gũi. Sản phẩm hiện đang có chương trình ưu đãi cực lớn, giảm giá 90% từ 1,234,570đ chỉ còn 123,456đ.\n\n3. **Bộ ruồi câu cá Walt\'s Worm Jig (Mã 20):** Dành cho những ai yêu thích hoạt động ngoài trời, đây là loại ruồi câu cá Euro Nymphing phổ biến, mô phỏng ấu trùng caddis tự nhiên. Sản phẩm có nhiều kích thước và tùy chọn màu sắc khác nhau với mức giá từ 250,000đ đến 500,000đ.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần thêm thông tin chi tiết về sản phẩm nào, đừng ngần ngại cho mình biết nha.', '2026-07-09 10:53:09.000000', '[{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"},{\"product_id\":\"20\",\"url\":\"https://i.etsystatic.com/26202727/r/il/99fe09/5567543496/il_fullxfull.5567543496_bcnr.jpg\"},{\"product_id\":\"1805\",\"url\":\"https://i.etsystatic.com/9487154/c/1700/1700/399/166/il/e14cc6/4280898027/il_510x680.4280898027_oqj8.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
