INSERT INTO `chat_history` VALUES (70, 'Chào bạn, rất vui được hỗ trợ bạn thêm thông tin về sản phẩm này!\n\n**Mỹ thuật Heather Nature Ảnh In (Mã 1805)** là một tác phẩm nghệ thuật tinh tế, rất phù hợp để trang trí không gian sống hoặc làm quà tặng. Dưới đây là một số thông tin chi tiết về sản phẩm:\n\n*   **Chất liệu:** Được in trên giấy cotton 100% cao cấp với mực màu chuyên dụng, đảm bảo độ bền và khả năng chống phai màu lên đến hơn 100 năm.\n*   **Thiết kế:** Đây là bản in mỹ thuật lưu trữ từ bức ảnh thiên nhiên cây thạch nam nguyên bản, mang lại vẻ đẹp chân thực và nghệ thuật.\n*   **Kích thước:** Sản phẩm rất linh hoạt với nhiều tùy chọn kích thước từ 5x7 đến 16x20, giúp bạn dễ dàng lựa chọn phù hợp với vị trí treo tranh.\n*   **Giá bán:** 813,750đ.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần tư vấn thêm về cách chọn kích thước hoặc các thông tin khác, hãy cho mình biết nha.', '2026-07-09 10:53:39.000000', '[{\"product_id\":\"1805\",\"url\":\"https://i.etsystatic.com/9487154/c/1700/1700/399/166/il/e14cc6/4280898027/il_510x680.4280898027_oqj8.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'1', NULL);
INSERT INTO `chat_history` VALUES (71, '160', '2026-07-09 10:53:48.000000', NULL, 'user', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (72, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nSản phẩm có mã **160** mà bạn quan tâm chính là **Nến thơm sáp dừa Crocus**. Đây là một lựa chọn tuyệt vời để tạo không gian thư giãn cho ngôi nhà của bạn với những đặc điểm nổi bật sau:\n\n*   **Chất liệu:** Nến được làm từ sáp dừa bền vững, thân thiện với môi trường.\n*   **Trải nghiệm:** Sản phẩm sử dụng bấc gỗ, khi đốt sẽ tạo ra âm thanh tanh tách nhẹ nhàng rất thư thái.\n*   **Hương thơm:** Nến có hương hoa nghệ tây với khả năng tỏa hương tuyệt vời.\n*   **Thời gian sử dụng:** Lọ thủy tinh 8oz, thời gian đốt cháy lên đến hơn 55 giờ.\n*   **Giá bán:** 1,025,250đ.\n\nMời bạn xem các hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần thêm thông tin gì về mẫu nến này, đừng ngần ngại hỏi mình nha.', '2026-07-09 10:53:50.000000', '[{\"product_id\":\"160\",\"url\":\"https://i.etsystatic.com/28021565/r/il/a4c720/7928788026/il_1588xN.7928788026_5o7d.jpg\"},{\"product_id\":\"160\",\"url\":\"https://i.etsystatic.com/28021565/r/il/96d22d/7928788032/il_1588xN.7928788032_ifsd.jpg\"},{\"product_id\":\"160\",\"url\":\"https://i.etsystatic.com/28021565/r/il/c173a4/7976742019/il_1588xN.7976742019_d98o.jpg\"}]', 'assistant', '8f6c8b99-6ba3-478f-86bd-4ba8de1ffa47', 'user-1766022973', b'1', NULL);
