INSERT INTO `chat_history` VALUES (75, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm tại cửa hàng Thu Ngân!\n\nSản phẩm có mã 163 mà bạn đang tìm kiếm là **Kệ Gỗ Hepatica Chạm Khắc Bằng Tay**. Đây là một chiếc kệ nổi được làm từ gỗ óc chó nguyên khối, nổi bật với các chi tiết chạm khắc thủ công tinh xảo ở phần viền.\n\nDưới đây là một số thông tin chi tiết về sản phẩm:\n*   **Giá bán:** 1,618,500đ.\n*   **Kích thước:** Chiều dài 24 inch, độ sâu 6 inch.\n*   **Chất liệu:** Gỗ óc chó, được hoàn thiện bằng dầu sáp ong an toàn thực phẩm.\n*   **Đặc điểm:** Sản phẩm đã bao gồm đầy đủ các phụ kiện phần cứng để bạn dễ dàng lắp đặt lên tường.\n\nMời bạn xem hình ảnh của sản phẩm bên dưới nhé. Nếu cần hỗ trợ thêm thông tin gì, bạn cứ nhắn mình nha!', '2026-07-09 11:11:01.000000', '[{\"product_id\":\"163\",\"url\":\"https://i.etsystatic.com/65991936/r/il/324df2/8072324389/il_1588xN.8072324389_39un.jpg\"},{\"product_id\":\"163\",\"url\":\"https://i.etsystatic.com/65991936/r/il/486d1d/8072324381/il_1588xN.8072324381_pyn5.jpg\"},{\"product_id\":\"163\",\"url\":\"https://i.etsystatic.com/65991936/r/il/bf7821/8072324153/il_1588xN.8072324153_r8je.jpg\"}]', 'assistant', 'cf45401c-5e09-4f68-9e17-a28919cef0f3', 'user-1766022973', b'1', NULL);
