INSERT INTO `chat_history` VALUES (77, 'Chào bạn, rất vui được hỗ trợ bạn!\n\nTuy nhiên, mình là trợ lý ảo chuyên tư vấn các sản phẩm tại cửa hàng Thu Ngân, nên mình không có thông tin cập nhật về thời tiết hôm nay ạ. \n\nNếu bạn đang quan tâm đến các sản phẩm như áo hay các tác phẩm nghệ thuật tại cửa hàng, đừng ngần ngại cho mình biết nhé, mình rất sẵn lòng tư vấn giúp bạn!', '2026-07-09 11:12:05.000000', '[{\"product_id\":\"77\",\"url\":\"https://i.etsystatic.com/63125473/r/il/1372af/8016911479/il_1588xN.8016911479_8coj.jpg\"}]', 'assistant', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'0', NULL);
