INSERT INTO `chat_history` VALUES (79, 'Chào bạn, rất vui được giới thiệu đến bạn các sản phẩm trang sức độc đáo tại cửa hàng Thu Ngân. Hiện tại, chúng mình đang có một số mẫu nhẫn thiết kế rất ấn tượng, mời bạn tham khảo nhé:\n\n1. **Vòng tuyên bố Mugwort pha lê thô (Mã 318):** Chiếc nhẫn nổi bật với pha lê ngải cứu thô, được chế tác từ đồng thau tái chế. Điểm đặc biệt là dây đeo có thể điều chỉnh linh hoạt từ size 6-9. Mỗi viên pha lê đều là duy nhất về hình dáng và màu sắc. Giá sản phẩm là 1.074.500đ.\n\n2. **Vòng tuyên bố Mugwort pha lê thô (Mã 1182):** Đây là phiên bản khác của dòng nhẫn pha lê ngải cứu với thiết kế tương tự, mang vẻ đẹp tự nhiên và tinh tế. Giá sản phẩm là 1.496.500đ.\n\n3. **Nhẫn tuyên bố quả việt quất pha lê thô (Mã 1310):** Một thiết kế táo bạo với pha lê việt quất thô trên nền đồng thau tái chế, cũng có thể điều chỉnh kích cỡ từ 6-9. Sản phẩm này có giá 913.250đ.\n\nBạn có đang để mắt đến mẫu nào trong số này không? Nếu cần thêm thông tin chi tiết về sản phẩm nào, bạn cứ cho mình biết nhé!', '2026-07-09 11:13:16.000000', '[{\"product_id\":\"318\",\"url\":\"https://i.etsystatic.com/13316288/r/il/4391c7/5217611006/il_510x638.5217611006_hejv.jpg\"},{\"product_id\":\"1182\",\"url\":\"https://i.etsystatic.com/59957673/c/2008/2008/0/538/il/88e932/7916772458/il_510x680.7916772458_jo72.jpg\"},{\"product_id\":\"1310\",\"url\":\"https://i.etsystatic.com/59957673/c/1530/1530/394/629/il/617848/8021928688/il_510x680.8021928688_qpcn.jpg\"}]', 'assistant', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (80, '1. **Vòng tuyên bố Mugwort pha lê thô (Mã 318)', '2026-07-09 11:13:34.000000', NULL, 'user', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (81, 'Chào bạn, cảm ơn bạn đã quan tâm đến chiếc **Vòng tuyên bố Mugwort pha lê thô (Mã 318)** này nhé! Đây là một trong những thiết kế rất đặc biệt tại cửa hàng Thu Ngân.\n\nSản phẩm này được chế tác từ đồng thau tái chế, nổi bật với viên pha lê ngải cứu thô mang vẻ đẹp tự nhiên, độc bản – nghĩa là mỗi chiếc nhẫn sẽ có hình dáng và màu sắc tinh thể riêng biệt, không chiếc nào giống chiếc nào. Một điểm cộng lớn là phần dây đeo có thể điều chỉnh linh hoạt từ size 6 đến 9, giúp bạn dễ dàng đeo vừa vặn.\n\nĐây là hình ảnh của sản phẩm để bạn dễ dàng quan sát vẻ đẹp của nó ạ:', '2026-07-09 11:13:36.000000', '[{\"product_id\":\"318\",\"url\":\"https://i.etsystatic.com/13316288/r/il/4391c7/5217611006/il_510x638.5217611006_hejv.jpg\"}]', 'assistant', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'1', 'http://localhost:3000/product/318');
INSERT INTO `chat_history` VALUES (82, 'thông tin dây chuyền', '2026-07-10 09:03:07.000000', NULL, 'user', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (83, 'Chào bạn, rất vui được hỗ trợ bạn! Tại cửa hàng Thu Ngân, chúng mình hiện có một mẫu dây chuyền rất đặc biệt dành cho những ai yêu thích tốc độ và sự cá tính, đó là:\n\n**Vòng cổ mặt dây chuyền Circuit of the Americas (COTA)**\n\nĐây là món phụ kiện được thiết kế lấy cảm hứng từ đường đua đẳng cấp thế giới tại Austin, Texas. Sản phẩm được chế tác tỉ mỉ với màu vàng (Gold) sang trọng, mang đến vẻ ngoài mạnh mẽ và đầy ấn tượng. Đây là lựa chọn hoàn hảo nếu bạn muốn thể hiện niềm đam mê với thế giới đua xe.\n\nSản phẩm hiện có giá là 400.000đ. Mời bạn xem hình ảnh của chiếc vòng cổ này bên dưới nhé:', '2026-07-10 09:03:13.000000', '[{\"product_id\":\"7\",\"url\":\"https://i.etsystatic.com/45526673/r/il/53625f/5195438654/il_fullxfull.5195438654_1hyb.jpg\"},{\"product_id\":\"7\",\"url\":\"https://i.etsystatic.com/45526673/r/il/2aa375/5243669213/il_fullxfull.5243669213_t2hg.jpg\"}]', 'assistant', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'1', 'http://localhost:3000/product/7');
INSERT INTO `chat_history` VALUES (84, 'sản phẩm 2011', '2026-07-10 09:10:15.000000', NULL, 'user', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'0', NULL);
INSERT INTO `chat_history` VALUES (85, 'Chào bạn, rất vui được hỗ trợ bạn! Sản phẩm có mã 2011 mà bạn quan tâm là **Bông tai bạc hình quả lý gai được rèn thủ công**.\n\nĐây là một thiết kế rất tinh tế với kết cấu quả lý gai độc đáo. Sản phẩm được chế tác thủ công, phần trụ cột làm bằng bạc 925 cao cấp với mặt sau hình con bướm chắc chắn. Đặc biệt, bông tai này không chứa niken và không gây dị ứng, rất an toàn cho người sử dụng. Sản phẩm có đường kính khoảng 10mm, mang lại vẻ ngoài nhỏ nhắn nhưng đầy ấn tượng.\n\nGiá của đôi bông tai này là 906.750đ. Mời bạn xem hình ảnh của sản phẩm bên dưới nhé:', '2026-07-10 09:10:16.000000', '[{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/37c53a/6802622528/il_1588xN.6802622528_sicy.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/9c8338/7687943335/il_1588xN.7687943335_pxna.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/415c66/7687997535/il_1588xN.7687997535_fdu5.jpg\"}]', 'assistant', '8894c19e-0f04-4408-85ff-de7d33b46134', 'user-1766022973', b'1', 'http://localhost:3000/product/2011');
