INSERT INTO `chat_history` VALUES (88, 'Chào bạn, rất xin lỗi bạn nhưng hiện tại cửa hàng Thu Ngân của chúng mình không kinh doanh điện thoại iPhone 17 ạ. Cửa hàng mình hiện đang chuyên về các sản phẩm túi xách, ví và trang sức thủ công.\n\nNếu bạn quan tâm đến các phụ kiện thời trang như túi xách hay trang sức, mình rất sẵn lòng tư vấn thêm cho bạn nhé!', '2026-07-10 10:10:52.000000', '[{\"product_id\":\"1770\",\"url\":\"https://i.etsystatic.com/35872205/r/il/54a928/3981193334/il_510x680.3981193334_i7jw.jpg\"},{\"product_id\":\"1737\",\"url\":\"https://i.etsystatic.com/13305942/r/il/eeec6e/8166777347/il_510x680.8166777347_fyad.jpg\"},{\"product_id\":\"1756\",\"url\":\"https://i.etsystatic.com/65358039/r/il/720192/7888632018/il_510x680.7888632018_tncr.jpg\"}]', 'assistant', 'f1cc791e-7dc2-4bae-a8c0-c805047eed18', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (91, 'sản phẩm 2011', '2026-07-10 17:22:07.000000', NULL, 'user', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (92, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm tại cửa hàng Thu Ngân!\n\nSản phẩm có mã 2011 mà bạn đang tìm kiếm là đôi **Bông tai bạc hình quả lý gai được rèn thủ công**. Đây là một thiết kế rất tinh tế với các đặc điểm nổi bật như sau:\n\n*   **Chất liệu:** Bạc 925 cao cấp, không chứa niken và không gây dị ứng, an toàn cho da.\n*   **Thiết kế:** Bông tai dạng đinh tán, được rèn thủ công với kết cấu hình quả lý gai độc đáo.\n*   **Kích thước:** Đường kính khoảng 10 mm, đi kèm mặt sau hình con bướm chắc chắn.\n*   **Giá bán:** 906,750đ.\n\nĐây là một món phụ kiện rất xinh xắn và tỉ mỉ. Mời bạn xem hình ảnh sản phẩm bên dưới nhé!', '2026-07-10 17:22:08.000000', '[{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/37c53a/6802622528/il_1588xN.6802622528_sicy.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/9c8338/7687943335/il_1588xN.7687943335_pxna.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/415c66/7687997535/il_1588xN.7687997535_fdu5.jpg\"}]', 'assistant', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/2011');
INSERT INTO `chat_history` VALUES (93, 'sản phẩm về túi', '2026-07-10 17:22:28.000000', NULL, 'user', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (94, 'Chào bạn, tại cửa hàng Thu Ngân hiện đang có một số mẫu túi và ba lô rất chất lượng. Dưới đây là các sản phẩm hiện có để bạn tham khảo nhé:\n\n1. **Túi cá sấu (Mã 2023):** Một chiếc túi có thiết kế độc đáo, hiện đang được ưu đãi giảm giá 18%, chỉ còn 100,000đ (giá gốc 122,300đ).\n2. **Ba lô vải bạt Mugwort (Mã 1290):** Đây là dòng ba lô vải sáp hạng nặng cao cấp với viền da ngải cứu, có khả năng chống thấm nước, ngăn đựng laptop 15 inch và dung tích 20L. Giá sản phẩm là 4,163,750đ.\n3. **Ba lô vải bạt Mugwort (Mã 426):** Tương tự như mẫu trên với chất liệu vải sáp bền bỉ, thiết kế tiện dụng cho công việc và du lịch. Giá sản phẩm là 3,596,000đ.\n\nBạn đang quan tâm đến mẫu nào trong số các sản phẩm trên để mình tư vấn kỹ hơn cho bạn nhé?', '2026-07-10 17:22:30.000000', '[{\"product_id\":\"2023\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768496/woljjbfo1w7ro88i6npj.png\"},{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"}]', 'assistant', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (95, 'túi 1290', '2026-07-10 17:22:42.000000', NULL, 'user', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (96, 'Chào bạn, cảm ơn bạn đã quan tâm đến mẫu ba lô này tại cửa hàng Thu Ngân!\n\nBa lô vải bạt Mugwort (mã 1290) là một sản phẩm rất chất lượng và bền bỉ, phù hợp cho cả công việc lẫn những chuyến đi. Dưới đây là các thông tin chi tiết về sản phẩm:\n\n*   **Chất liệu:** Vải sáp hạng nặng cao cấp, kết hợp cùng viền da ngải cứu tạo nên vẻ ngoài sang trọng và chắc chắn.\n*   **Khả năng bảo vệ:** Bề mặt ngoài có khả năng chống thấm nước tốt, giúp bảo vệ đồ đạc bên trong.\n*   **Tiện ích:** Ba lô có ngăn đựng máy tính xách tay (laptop) có đệm, vừa vặn cho các dòng máy 15 inch. Ngoài ra còn có các túi phụ ở cả bên trong và bên ngoài để bạn sắp xếp đồ dùng cá nhân.\n*   **Thiết kế:** Sử dụng phần cứng bằng đồng cổ tạo điểm nhấn cổ điển.\n*   **Dung tích:** 20L, rất thoải mái để đựng đồ dùng hàng ngày.\n*   **Giá bán:** 4,163,750đ.\n\nĐây là một lựa chọn tuyệt vời nếu bạn đang tìm kiếm một chiếc ba lô bền, đẹp và đa năng. Mời bạn xem hình ảnh sản phẩm bên dưới nhé!', '2026-07-10 17:22:44.000000', '[{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"1289\",\"url\":\"https://i.etsystatic.com/32226390/c/1024/1024/264/0/il/7162a8/7785572716/il_510x680.7785572716_e96u.jpg\"},{\"product_id\":\"2023\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768496/woljjbfo1w7ro88i6npj.png\"}]', 'assistant', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (97, '1290', '2026-07-10 17:23:06.000000', NULL, 'user', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (98, 'Chào bạn, rất vui được hỗ trợ bạn thêm về mẫu ba lô này!\n\nNhư mình đã chia sẻ, **Ba lô vải bạt Mugwort (mã 1290)** là một sản phẩm rất được ưa chuộng tại cửa hàng Thu Ngân nhờ sự kết hợp hoàn hảo giữa độ bền của vải sáp hạng nặng và vẻ đẹp tinh tế từ viền da ngải cứu.\n\nĐây là một chiếc ba lô lý tưởng cho những ai cần một người bạn đồng hành chắc chắn, có khả năng chống thấm nước tốt và bảo vệ an toàn cho laptop 15 inch của bạn. Với dung tích 20L và các ngăn chứa được thiết kế thông minh, sản phẩm này cực kỳ tiện lợi cho cả nhu cầu đi làm hàng ngày hay những chuyến du lịch ngắn ngày.\n\nMời bạn xem lại hình ảnh của sản phẩm bên dưới nhé!', '2026-07-10 17:23:07.000000', '[{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"}]', 'assistant', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/1290');
