INSERT INTO `chat_history` VALUES (100, 'Chào bạn, cảm ơn bạn đã quan tâm đến mẫu ba lô mã 426 tại cửa hàng Thu Ngân!\n\nĐây là một chiếc ba lô vải bạt Mugwort rất bền bỉ và phong cách. Dưới đây là các thông tin chi tiết về sản phẩm này:\n\n*   **Chất liệu:** Vải sáp hạng nặng cao cấp, kết hợp cùng viền da ngải cứu tạo nên vẻ ngoài sang trọng và chắc chắn.\n*   **Khả năng bảo vệ:** Bề mặt ngoài có khả năng chống thấm nước, giúp bảo vệ đồ đạc bên trong an toàn.\n*   **Tiện ích:** Ba lô được trang bị ngăn đựng máy tính xách tay (laptop) có đệm, vừa vặn cho các dòng máy 15 inch. Ngoài ra, sản phẩm còn có các túi phụ ở cả bên trong và bên ngoài để bạn dễ dàng sắp xếp đồ dùng cá nhân.\n*   **Thiết kế:** Sử dụng phần cứng bằng đồng cổ tạo điểm nhấn cổ điển và tinh tế.\n*   **Dung tích:** 20L, rất thoải mái cho nhu cầu đi làm hoặc đi du lịch.\n*   **Giá bán:** 3,596,000đ.\n\nĐây là một lựa chọn tuyệt vời nếu bạn đang tìm kiếm một chiếc ba lô vừa bền, vừa có tính thẩm mỹ cao. Mời bạn xem hình ảnh của sản phẩm bên dưới nhé!', '2026-07-10 17:23:22.000000', '[{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"},{\"product_id\":\"265\",\"url\":\"https://i.etsystatic.com/5608944/r/il/2999ec/7045383913/il_510x680.7045383913_o3m2.jpg\"},{\"product_id\":\"649\",\"url\":\"https://i.etsystatic.com/35676435/r/il/da8a86/7101304525/il_510x638.7101304525_eat5.jpg\"}]', 'assistant', '024b7fa4-8fe6-4001-8b87-af59136520bf', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
