INSERT INTO `chat_history` VALUES (106, 'Chào bạn, có vẻ như bạn đang tìm kiếm sản phẩm có tên là \"abccbahsjas\" phải không ạ?\n\nĐây là thông tin về sản phẩm này tại cửa hàng Thu Ngân:\n- **Tên sản phẩm:** abccbahsjas\n- **Danh mục:** Phụ kiện\n- **Giá:** 769,891đ\n- **Mô tả:** à\n\nMời bạn xem hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần thêm thông tin gì, đừng ngần ngại hỏi mình nha.', '2026-07-10 17:58:14.000000', '[{\"product_id\":\"2029\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781764180/b4ywb8aszch9raro8jqi.jpg\"},{\"product_id\":\"1262\",\"url\":\"https://i.etsystatic.com/53553642/r/il/e2f8e5/8113125601/il_510x680.8113125601_b9x3.jpg\"},{\"product_id\":\"782\",\"url\":\"https://i.etsystatic.com/15964968/r/il/b8081d/5480019605/il_510x638.5480019605_4mul.jpg\"}]', 'assistant', '3e3563e2-baa6-4c7e-8b9f-6d7c1e3dac6a', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
