INSERT INTO `chat_history` VALUES (108, 'Chào bạn, rất tiếc là hiện tại cửa hàng Thu Ngân bên mình không có kinh doanh sản phẩm iPhone 17 ạ. \n\nHiện tại cửa hàng mình đang có các sản phẩm như Mỹ thuật Heather Nature, Thanh gội đầu rắn Hawkweed hoặc Ruby Terp Pearl. Nếu bạn quan tâm đến các sản phẩm này hoặc cần tìm kiếm món đồ nào khác, hãy cho mình biết nhé!', '2026-07-10 17:59:04.000000', '[{\"product_id\":\"77\",\"url\":\"https://i.etsystatic.com/63125473/r/il/1372af/8016911479/il_1588xN.8016911479_8coj.jpg\"},{\"product_id\":\"1711\",\"url\":\"https://i.etsystatic.com/16124091/c/2000/2000/438/0/il/3b747e/7791052631/il_510x680.7791052631_mj3w.jpg\"},{\"product_id\":\"5\",\"url\":\"https://i.etsystatic.com/43838194/r/il/46505d/5026136200/il_fullxfull.5026136200_axes.jpg\"}]', 'assistant', '3e3563e2-baa6-4c7e-8b9f-6d7c1e3dac6a', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
