INSERT INTO `chat_history` VALUES (110, 'Chào bạn, sản phẩm có mã 2011 mà bạn đang quan tâm là **Bông tai bạc hình quả lý gai được rèn thủ công** tại cửa hàng Thu Ngân ạ.\n\nĐây là một món trang sức rất tinh tế với các thông tin chi tiết như sau:\n- **Danh mục:** Trang sức\n- **Giá:** 906,750đ\n- **Mô tả:** Bông tai đinh tán được rèn thủ công với kết cấu hình quả lý gai độc đáo. Sản phẩm được làm từ bạc 925, có mặt sau hình con bướm, không chứa niken và không gây dị ứng. Đường kính bông tai khoảng 10 mm.\n\nMời bạn xem hình ảnh của sản phẩm bên dưới nhé! Nếu bạn cần hỗ trợ thêm thông tin gì, đừng ngần ngại hỏi mình nha.', '2026-07-10 17:59:18.000000', '[{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/37c53a/6802622528/il_1588xN.6802622528_sicy.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/9c8338/7687943335/il_1588xN.7687943335_pxna.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/415c66/7687997535/il_1588xN.7687997535_fdu5.jpg\"}]', 'assistant', '3e3563e2-baa6-4c7e-8b9f-6d7c1e3dac6a', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/2011');
