INSERT INTO `chat_history` VALUES (112, 'Chào bạn, rất xin lỗi bạn nhưng hiện tại trong hệ thống dữ liệu của cửa hàng Thu Ngân không có thông tin về sản phẩm có hình dáng như trong ảnh mà bạn vừa gửi ạ.\n\nCó thể đây là một sản phẩm không nằm trong danh mục kinh doanh hiện tại của cửa hàng mình. Nếu bạn quan tâm đến các sản phẩm khác như trang sức bạc hoặc các dòng sản phẩm chăm sóc cá nhân (thanh gội đầu, xà phòng thủ công) mà mình đã giới thiệu trước đó, hãy cho mình biết để mình hỗ trợ bạn nhé!', '2026-07-10 17:59:37.000000', '[{\"product_id\":\"335\",\"url\":\"https://i.etsystatic.com/12041095/r/il/dba314/2396376118/il_510x638.2396376118_kpnc.jpg\"},{\"product_id\":\"1934\",\"url\":\"https://i.etsystatic.com/13673219/r/il/2e4f7e/1481588854/il_510x680.1481588854_nxx2.jpg\"},{\"product_id\":\"367\",\"url\":\"https://i.etsystatic.com/15918929/r/il/e0b0a0/2000678003/il_510x638.2000678003_qp5w.jpg\"}]', 'assistant', '3e3563e2-baa6-4c7e-8b9f-6d7c1e3dac6a', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
