INSERT INTO `chat_history` VALUES (127, 'Chào bạn, ngoài mẫu túi cá sấu kể trên, cửa hàng Thu Ngân hiện còn có mẫu **Ba lô vải bạt Mugwort** rất chất lượng và bền bỉ ạ.\n\nSản phẩm này được làm từ vải sáp hạng nặng với viền da ngải cứu, có khả năng chống thấm nước tốt và ngăn đựng máy tính xách tay lên đến 15 inch, rất phù hợp để đi học hoặc đi làm. Hiện tại cửa hàng đang có hai mức giá cho mẫu ba lô này là 4,163,750đ và 3,596,000đ tùy theo phiên bản ạ.\n\nMời bạn xem hình ảnh và thông tin chi tiết của sản phẩm bên dưới nhé!', '2026-07-10 18:10:23.000000', '[{\"product_id\":\"2023\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768496/woljjbfo1w7ro88i6npj.png\"},{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
