INSERT INTO `chat_history` VALUES (129, 'Chào bạn, có vẻ như bạn đang quan tâm đến mẫu **Ba lô vải bạt Mugwort** đúng không ạ?\n\nĐây là một sản phẩm rất bền bỉ và phong cách tại cửa hàng Thu Ngân. Ba lô được làm từ chất liệu vải sáp hạng nặng kết hợp với viền da ngải cứu, có khả năng chống thấm nước rất tốt. Sản phẩm có dung tích 20L, được trang bị ngăn đựng máy tính xách tay có đệm (vừa cho laptop 15 inch) cùng nhiều túi phụ bên trong và bên ngoài rất tiện lợi. Điểm nhấn của mẫu này là phần cứng bằng đồng cổ tạo nên vẻ ngoài rất sang trọng và cổ điển.\n\nHiện tại, sản phẩm này đang có giá là 3,596,000đ. Mời bạn xem hình ảnh và thông tin chi tiết của sản phẩm bên dưới nhé!', '2026-07-10 18:10:36.000000', '[{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/426');
