INSERT INTO `chat_history` VALUES (131, 'Chào bạn, đúng rồi ạ! Mẫu **Ba lô vải bạt Mugwort** với mức giá 4,163,750đ là phiên bản cao cấp hơn tại cửa hàng Thu Ngân.\n\nSản phẩm này được làm từ chất liệu vải sáp hạng nặng vô cùng bền bỉ, kết hợp cùng viền da ngải cứu tinh tế và phần cứng bằng đồng cổ tạo nên vẻ ngoài rất sang trọng. Ba lô có dung tích 20L, khả năng chống thấm nước tốt và được trang bị ngăn đệm chuyên dụng cho laptop 15 inch, rất tiện lợi cho việc đi học hoặc đi làm hàng ngày.\n\nMời bạn xem hình ảnh và thông tin chi tiết của sản phẩm bên dưới nhé!', '2026-07-10 18:10:59.000000', '[{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"},{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"264\",\"url\":\"https://i.etsystatic.com/18966660/r/il/ae08d5/7193979379/il_510x680.7193979379_1jg5.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
