INSERT INTO `chat_history` VALUES (137, 'Chào bạn, có lẽ bạn đang muốn nhắc đến mẫu **Ba lô vải bạt Mugwort** phiên bản cao cấp với mức giá 4,163,750đ tại cửa hàng Thu Ngân đúng không ạ?\n\nĐây là mẫu ba lô được làm từ vải sáp hạng nặng với viền da ngải cứu, có khả năng chống thấm nước rất tốt và ngăn đựng laptop 15 inch chuyên dụng. Với thiết kế bền bỉ cùng phần cứng bằng đồng cổ sang trọng, đây chắc chắn là một lựa chọn tuyệt vời cho nhu cầu sử dụng hàng ngày của bạn.\n\nMời bạn xem hình ảnh và thông tin chi tiết của sản phẩm bên dưới nhé!', '2026-07-10 18:11:41.000000', '[{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"},{\"product_id\":\"1674\",\"url\":\"https://i.etsystatic.com/15064228/r/il/61eb0e/7344392397/il_510x680.7344392397_gp51.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
