INSERT INTO `chat_history` VALUES (139, 'Chào bạn, tại cửa hàng Thu Ngân hiện đang có 3 mẫu ba lô vải sáp rất chất lượng với thiết kế bền bỉ và phong cách cổ điển. Bạn có thể tham khảo thông tin chi tiết dưới đây nhé:\n\n1. **Ba lô vải bạt Mugwort (Giá: 4,163,750đ):** Làm từ vải sáp hạng nặng với viền da ngải cứu, dung tích 20L, có ngăn chống sốc cho laptop 15 inch và phần cứng bằng đồng cổ.\n2. **Ba lô vải Rowan sáp (Giá: 5,166,750đ):** Tương tự với dung tích 20L và khả năng chống thấm nước, nhưng sử dụng viền da thanh lương trà sang trọng.\n3. **Ba lô vải màu sáp (Giá: 5,461,000đ):** Mẫu cao cấp với viền da màu nâu đỏ, thiết kế chắc chắn và đầy đủ các ngăn tiện ích như các mẫu trên.\n\nTất cả các mẫu đều có khả năng chống thấm nước tốt và rất phù hợp để đựng laptop 15 inch. Bạn đang quan tâm đến mẫu nào trong số này để mình tư vấn kỹ hơn không ạ? Mời bạn xem hình ảnh các sản phẩm bên dưới nhé!', '2026-07-10 18:11:55.000000', '[{\"product_id\":\"330\",\"url\":\"https://i.etsystatic.com/62236217/r/il/f83d88/7999052681/il_510x638.7999052681_arhk.jpg\"},{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"746\",\"url\":\"https://i.etsystatic.com/9318089/r/il/4aaff4/6016573369/il_510x638.6016573369_g623.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (140, '**Ba lô vải bạt Mugwort (Giá: 4,163,750đ):** Làm từ vải sáp hạng nặng với viền da ngải cứu, dung tích 20L, có ngăn chống sốc cho laptop 15 inch và phần cứng bằng đồng cổ', '2026-07-10 18:12:10.000000', NULL, 'user', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (141, 'Chào bạn, đúng rồi ạ! Đây chính là mẫu **Ba lô vải bạt Mugwort** phiên bản cao cấp với mức giá 4,163,750đ tại cửa hàng Thu Ngân mà bạn đang quan tâm.\n\nSản phẩm này được thiết kế rất tỉ mỉ với chất liệu vải sáp hạng nặng bền bỉ, kết hợp cùng viền da ngải cứu tinh tế và các chi tiết phần cứng bằng đồng cổ tạo nên vẻ ngoài vô cùng sang trọng. Với dung tích 20L, khả năng chống thấm nước tốt và ngăn đệm chuyên dụng cho laptop 15 inch, đây là người bạn đồng hành lý tưởng cho công việc hoặc những chuyến đi của bạn.\n\nMời bạn xem hình ảnh chi tiết của sản phẩm bên dưới nhé! Nếu bạn cần hỗ trợ thêm thông tin gì, đừng ngần ngại nhắn cho mình nha.', '2026-07-10 18:12:13.000000', '[{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"},{\"product_id\":\"426\",\"url\":\"https://i.etsystatic.com/59490453/r/il/8ef0b5/8087809817/il_510x638.8087809817_ekcf.jpg\"},{\"product_id\":\"1674\",\"url\":\"https://i.etsystatic.com/15064228/r/il/61eb0e/7344392397/il_510x680.7344392397_gp51.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (142, 'bạn cung cấp tôi link mua hàng **Ba lô vải bạt Mugwort (Giá: 4,163,750đ):** Làm từ vải sáp hạng nặng với viền da ngải cứu, dung tích 20L, có ngăn chống sốc cho laptop 15 inch và phần cứng bằng đồng cổ', '2026-07-10 18:12:23.000000', NULL, 'user', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
