INSERT INTO `chat_history` VALUES (145, 'Chào bạn, rất xin lỗi bạn về sự bất tiện này nhé! Có thể do lỗi hiển thị tạm thời của hệ thống nên nút mua hàng chưa xuất hiện ngay.\n\nBạn vui lòng thử tải lại trang hoặc kiểm tra lại giúp mình xem nút \"Xem chi tiết & mua hàng\" đã hiện ra chưa nhé. Nếu vẫn không thấy, bạn có thể cho mình biết để mình kiểm tra lại kỹ thuật hoặc hỗ trợ bạn cách khác để đặt hàng mẫu **Ba lô vải bạt Mugwort** này nhé!\n\nCảm ơn bạn đã kiên nhẫn ạ!', '2026-07-10 18:12:32.000000', '[{\"product_id\":\"9\",\"url\":\"https://i.etsystatic.com/23385463/r/il/b8a634/5873079091/il_fullxfull.5873079091_djmj.jpg\"},{\"product_id\":\"2033\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1783581165/zqublmgamblsurrusplc.jpg\"},{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (146, '2015', '2026-07-10 18:12:40.000000', NULL, 'user', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (147, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm tại cửa hàng Thu Ngân!\n\nMã số **2015** mà bạn vừa nhập chính là sản phẩm **Nến sáp ong Lingonberry đổ bằng tay**. Đây là một sản phẩm rất tinh tế thuộc danh mục Nhà cửa & cuộc sống với mức giá 609,750đ.\n\nDưới đây là một số thông tin chi tiết về sản phẩm này:\n*   **Đặc điểm:** Nến trụ được làm từ sáp ong nguyên chất, đổ thủ công bằng tay với hỗn hợp tinh dầu nam việt quất.\n*   **Thời gian sử dụng:** Lưu hương lên tới 40 giờ với hương mật ong tự nhiên dịu nhẹ.\n*   **Chất lượng:** Sản phẩm hoàn toàn tự nhiên, không chứa chất phụ gia hay hương thơm nhân tạo.\n*   **Kích thước:** Đường kính 3 inch, chiều cao 4 inch.\n\nĐây là lựa chọn tuyệt vời để tạo không gian thư giãn và ấm cúng cho ngôi nhà của bạn. Mời bạn xem hình ảnh sản phẩm bên dưới nhé!', '2026-07-10 18:12:42.000000', '[{\"product_id\":\"2015\",\"url\":\"https://i.etsystatic.com/14154111/r/il/7d0553/3167338870/il_1588xN.3167338870_toz7.jpg\"},{\"product_id\":\"2015\",\"url\":\"https://i.etsystatic.com/14154111/r/il/26b62f/3167340666/il_1588xN.3167340666_kp7z.jpg\"},{\"product_id\":\"2015\",\"url\":\"https://i.etsystatic.com/14154111/r/il/cc9a52/3221393123/il_1588xN.3221393123_itx8.jpg\"}]', 'assistant', '70c25f66-19e9-47b6-96dd-04ec7f2a4275', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/2015');
INSERT INTO `chat_history` VALUES (148, 'hello', '2026-07-10 19:04:48.000000', NULL, 'user', 'd65b3630-fb4e-4ce1-ab0d-0548d919bc1e', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
INSERT INTO `chat_history` VALUES (149, 'Chào bạn! Rất vui được hỗ trợ bạn tại cửa hàng Thu Ngân. Hôm nay mình có thể giúp gì cho bạn trong việc tìm kiếm sản phẩm ưng ý không ạ? \n\nHiện tại cửa hàng đang có một số sản phẩm nổi bật như bông tai pha lê thủ công hay bộ trò chơi ghép hình bằng gỗ rất thú vị. Bạn đang quan tâm đến sản phẩm nào không ạ?', '2026-07-10 19:04:52.000000', '[{\"product_id\":\"1372\",\"url\":\"https://i.etsystatic.com/31087632/r/il/1b237c/7336676577/il_510x680.7336676577_15zq.jpg\"},{\"product_id\":\"508\",\"url\":\"https://i.etsystatic.com/19793211/r/il/cb1c07/4969284594/il_510x638.4969284594_f56v.jpg\"},{\"product_id\":\"1459\",\"url\":\"https://i.etsystatic.com/17305851/c/1714/1714/723/604/il/449a36/7908514447/il_510x680.7908514447_ompa.jpg\"}]', 'assistant', 'd65b3630-fb4e-4ce1-ab0d-0548d919bc1e', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
