INSERT INTO `chat_history` VALUES (151, 'Chào bạn, rất vui được giới thiệu đến bạn các mẫu bông tai pha lê thủ công tại cửa hàng Thu Ngân. Hiện tại chúng mình có 3 mẫu thiết kế dạng vòng quấn dây rất tinh tế, được làm từ bạc sterling 20 thước, đường kính 35mm và rất nhẹ nhàng khi đeo hàng ngày:\n\n1. **Bông tai pha lê Thistle có dây**: Thiết kế với điểm nhấn pha lê hình cây kế, giá 1,330,250đ.\n2. **Bông tai pha lê bằng gỗ lũa có dây**: Thiết kế độc đáo với pha lê gỗ lũa, giá 1,092,000đ.\n3. **Bông tai pha lê bạch đậu khấu có dây**: Thiết kế sang trọng với pha lê bạch đậu khấu, giá 1,622,250đ.\n\nBạn đang quan tâm đến mẫu nào trong số các sản phẩm trên để mình tư vấn kỹ hơn cho bạn nhé? Mời bạn xem hình ảnh các sản phẩm bên dưới ạ!', '2026-07-10 19:05:13.000000', '[{\"product_id\":\"572\",\"url\":\"https://i.etsystatic.com/7777448/r/il/0c49b2/7702931243/il_510x638.7702931243_4k7j.jpg\"},{\"product_id\":\"348\",\"url\":\"https://i.etsystatic.com/14724467/r/il/35121d/4715584254/il_510x638.4715584254_k80y.jpg\"},{\"product_id\":\"1596\",\"url\":\"https://i.etsystatic.com/17618956/r/il/fd7bc5/6754178442/il_510x680.6754178442_591c.jpg\"}]', 'assistant', 'd65b3630-fb4e-4ce1-ab0d-0548d919bc1e', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
