INSERT INTO `chat_history` VALUES (153, 'Chào bạn, cảm ơn bạn đã quan tâm đến mẫu **Bông tai pha lê Thistle có dây** nhé!\n\nĐây là một lựa chọn rất tinh tế và thanh lịch. Sản phẩm này được chế tác thủ công từ dây bạc sterling 20 thước, với điểm nhấn là viên pha lê hình cây kế độc đáo. Với đường kính vòng 35mm, đôi bông tai này rất nhẹ và thoải mái, cực kỳ phù hợp để bạn đeo hàng ngày hoặc phối cùng các trang phục dạo phố. Sản phẩm hiện có giá là 1,307,250đ và đang nhận được đánh giá rất tốt từ khách hàng.\n\nMời bạn xem hình ảnh chi tiết của sản phẩm bên dưới nhé!', '2026-07-10 19:05:23.000000', '[{\"product_id\":\"1436\",\"url\":\"https://i.etsystatic.com/7258781/r/il/7c6204/5109477104/il_510x680.5109477104_m9oc.jpg\"}]', 'assistant', 'd65b3630-fb4e-4ce1-ab0d-0548d919bc1e', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/1436');
