INSERT INTO `chat_history` VALUES (155, 'Chào bạn, cảm ơn bạn đã quan tâm đến mẫu **Bông tai pha lê bạch đậu khấu có dây** nhé!\n\nĐây là một thiết kế rất sang trọng và tinh tế trong bộ sưu tập trang sức thủ công của cửa hàng. Sản phẩm được chế tác tỉ mỉ từ dây bạc sterling 20 thước, nổi bật với viên pha lê bạch đậu khấu đầy cuốn hút. Với đường kính vòng 35mm, đôi bông tai này được thiết kế để đảm bảo sự nhẹ nhàng và thoải mái tối đa, rất phù hợp để bạn đeo hàng ngày mà vẫn giữ được vẻ ngoài thanh lịch. Sản phẩm hiện có giá là 1,622,250đ và đang nhận được đánh giá rất cao từ khách hàng.\n\nMời bạn xem hình ảnh chi tiết của sản phẩm bên dưới nhé!', '2026-07-10 19:06:03.000000', '[{\"product_id\":\"1596\",\"url\":\"https://i.etsystatic.com/17618956/r/il/fd7bc5/6754178442/il_510x680.6754178442_591c.jpg\"}]', 'assistant', 'd65b3630-fb4e-4ce1-ab0d-0548d919bc1e', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/1596');
