INSERT INTO `chat_history` VALUES (189, 'Chào bạn, rất xin lỗi vì sự bất tiện này! Có vẻ như mình đã làm bạn bối rối. Để mình liệt kê lại các sản phẩm hiện có tại cửa hàng Thu Ngân để bạn dễ theo dõi nhé:\n\n**Về túi và ba lô:**\n1. **Túi cá sấu**: Mẫu túi thời trang, giá ưu đãi chỉ còn 100,000đ (giá gốc 122,300đ).\n2. **Ba lô vải bạt Mugwort**: Dòng cao cấp, chống thấm nước, có ngăn đựng laptop 15 inch. Giá từ 3,596,000đ đến 4,163,750đ.\n\n**Ngoài ra, cửa hàng mình còn có các sản phẩm khác như:**\n3. **Áo \"ăn cơm chưa\"**: Một chiếc áo in chữ độc đáo, đang được giảm giá cực sốc 90% chỉ còn 123,456đ (giá gốc 1,234,570đ).\n4. **Đồ chơi ghép hình bằng gỗ (vẽ tay)**:\n   - **Câu đố gỗ Hepatica**: Thiết kế thủ công, an toàn cho trẻ em, giá 684,250đ.\n   - **Câu đố gỗ cây tầm ma**: Thiết kế thủ công, an toàn cho trẻ em, giá 1,464,000đ.\n\nBạn đang quan tâm đến sản phẩm nào trong danh sách trên không ạ? Hãy cho mình biết để mình hỗ trợ bạn chi tiết hơn nhé!', '2026-07-10 19:15:47.000000', '[{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"},{\"product_id\":\"1459\",\"url\":\"https://i.etsystatic.com/17305851/c/1714/1714/723/604/il/449a36/7908514447/il_510x680.7908514447_ompa.jpg\"},{\"product_id\":\"211\",\"url\":\"https://i.etsystatic.com/39378069/r/il/1bd6c3/4930926876/il_510x680.4930926876_8zz5.jpg\"}]', 'assistant', '8b5a2106-36d7-493a-8ab3-3f6d9133c990', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
