INSERT INTO `chat_history` VALUES (199, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm ba lô vải bạt Mugwort tại cửa hàng Thu Ngân nhé!\n\nĐây là một dòng ba lô cao cấp với thiết kế rất bền bỉ và sang trọng. Sản phẩm được làm từ vải sáp hạng nặng kết hợp cùng viền da ngải cứu, mang lại khả năng chống thấm nước cực tốt. Ba lô có dung tích 20L, bên trong được trang bị ngăn đựng máy tính xách tay có đệm, vừa vặn cho các dòng laptop 15 inch. Ngoài ra, sản phẩm còn có các túi phụ bên ngoài và bên trong để bạn dễ dàng sắp xếp đồ đạc, cùng với phần cứng bằng đồng cổ tạo điểm nhấn rất tinh tế.\n\nSản phẩm hiện có giá là 4,163,750đ. Mời bạn xem hình ảnh của chiếc ba lô này bên dưới nhé. Bạn có cần mình hỗ trợ thêm thông tin gì để đặt hàng không ạ?', '2026-07-10 19:17:21.000000', '[{\"product_id\":\"1290\",\"url\":\"https://i.etsystatic.com/56635010/r/il/cec5db/8123850322/il_510x680.8123850322_g4re.jpg\"}]', 'assistant', '8b5a2106-36d7-493a-8ab3-3f6d9133c990', '20d428c7-bc91-49de-b321-17d40dae8a68', b'1', 'http://localhost:3000/product/1290');
