INSERT INTO `chat_history` VALUES (201, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm thiệp cưới màu nước táo gai tại cửa hàng Thu Ngân nhé!\n\nHiện tại, cửa hàng mình đang có 3 phiên bản cho mẫu thiệp cưới này với các mức giá khác nhau để bạn lựa chọn:\n\n1. **Phiên bản (ID 274):** Giá 263,250đ.\n2. **Phiên bản (ID 2002):** Giá 255,750đ.\n3. **Phiên bản (ID 1138):** Giá 175,500đ.\n\nTất cả các phiên bản đều được thiết kế vẽ tay với hình minh họa thực vật táo gai tinh tế, in trên chất liệu giấy bìa tái chế nặng 130lb cao cấp. Thiệp có kích thước A2, bên trong để trống để bạn tự do viết lời chúc và đi kèm với phong bì kraft tái chế rất sang trọng. Bạn có thể tùy chọn mua theo bộ 1, 5 hoặc 10 chiếc tùy theo nhu cầu sử dụng.\n\nMời bạn xem hình ảnh của sản phẩm bên dưới nhé. Bạn muốn chọn phiên bản nào để mình hỗ trợ bạn đặt hàng ạ?', '2026-07-10 19:17:37.000000', '[{\"product_id\":\"274\",\"url\":\"https://i.etsystatic.com/8189632/c/2000/2000/0/0/il/f791f3/6160929964/il_510x680.6160929964_1oan.jpg\"},{\"product_id\":\"1138\",\"url\":\"https://i.etsystatic.com/64956330/r/il/20afe9/7997010188/il_510x680.7997010188_q6yw.jpg\"},{\"product_id\":\"2002\",\"url\":\"https://i.etsystatic.com/24986416/r/il/e0b44e/5171049551/il_1588xN.5171049551_b9n6.jpg\"}]', 'assistant', '8b5a2106-36d7-493a-8ab3-3f6d9133c990', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
