INSERT INTO `chat_history` VALUES (223, 'Chào bạn, tại cửa hàng Thu Ngân hiện đang có mẫu bông tai bạc hình quả lý gai được rèn thủ công rất tinh tế và an toàn cho da (không chứa niken, không gây dị ứng). Mẫu này hiện có 3 mức giá khác nhau tùy theo từng phiên bản, mời bạn tham khảo nhé:\n\n1. **Bông tai bạc hình quả lý gai (ID: 1147)**: Giá 1,071,750đ.\n2. **Bông tai bạc hình quả lý gai (ID: 2011)**: Giá 906,750đ.\n3. **Bông tai bạc hình quả lý gai (ID: 283)**: Giá 486,250đ.\n\nCác sản phẩm đều có đường kính khoảng 10mm và sử dụng bạc 925 chất lượng cao. Bạn có muốn mình tư vấn kỹ hơn về mẫu nào không ạ? Mời bạn xem hình ảnh sản phẩm bên dưới nhé!', '2026-07-10 19:24:37.000000', '[{\"product_id\":\"1147\",\"url\":\"https://i.etsystatic.com/5180404/r/il/72afc9/6013087559/il_510x680.6013087559_8kdv.jpg\"},{\"product_id\":\"2011\",\"url\":\"https://i.etsystatic.com/54773317/r/il/37c53a/6802622528/il_1588xN.6802622528_sicy.jpg\"},{\"product_id\":\"283\",\"url\":\"https://i.etsystatic.com/54773317/c/1694/1694/643/0/il/415c66/7687997535/il_510x680.7687997535_fdu5.jpg\"}]', 'assistant', '28f0305f-3632-46b4-9739-26b169ee4c9b', '20d428c7-bc91-49de-b321-17d40dae8a68', b'0', NULL);
