INSERT INTO `chat_history` VALUES (326, 'Chào bạn, sản phẩm có mã 111 mà bạn quan tâm chính là **Thanh dầu gội Solid Elderflower** đến từ cửa hàng Thu Ngân ạ.\n\nĐây là một sản phẩm chăm sóc tóc rất tuyệt vời với các ưu điểm nổi bật:\n*   **Thành phần:** Chứa hỗn hợp thảo dược hoa cơm cháy, không chứa sunfat nên rất an toàn và phù hợp với mọi loại tóc.\n*   **Tiết kiệm:** Một thanh dầu gội có thể thay thế cho 2-3 chai dầu gội dạng lỏng thông thường và dùng được từ 60-80 lần giặt.\n*   **Thân thiện với môi trường:** Sản phẩm không tạo chất thải và đi kèm bao bì có thể phân hủy.\n\nSản phẩm hiện có giá là 374,750đ. Mời bạn xem hình ảnh và thông tin chi tiết của sản phẩm bên dưới nhé!', '2026-07-12 20:57:21.000000', '[{\"product_id\":\"111\",\"url\":\"https://i.etsystatic.com/27347086/r/il/6e1c4a/6919729853/il_1588xN.6919729853_opwl.jpg\"},{\"product_id\":\"111\",\"url\":\"https://i.etsystatic.com/27347086/r/il/496c0c/6867428598/il_1588xN.6867428598_qwv6.jpg\"},{\"product_id\":\"111\",\"url\":\"https://i.etsystatic.com/27347086/r/il/5352a4/6656333722/il_1588xN.6656333722_71zy.jpg\"}]', 'assistant', 'ec01b6c4-f915-401f-8c25-85ddd0a42ab1', '9ae5e6ec-3d7b-452b-ac1a-ea01c1d05b31', b'1', 'http://localhost:30000/product/111');
