INSERT INTO `chat_history` VALUES (342, 'Chào bạn! Có vẻ như bạn đang muốn tìm kiếm các sản phẩm tại cửa hàng Thu Ngân đúng không ạ?\n\nHiện tại cửa hàng mình đang có hai nhóm sản phẩm chính là dụng cụ câu cá và các loại xà phòng chăm sóc da. Dưới đây là một số sản phẩm nổi bật để bạn tham khảo nhé:\n\n1. **Về dụng cụ câu cá:** Mình có sản phẩm **6 - Walt\'s Worm Jig - Euro Nymphs**, đây là loại ruồi câu cá rất phổ biến, chuyên dùng để bắt chước ấu trùng caddis, cực kỳ hiệu quả cho các dòng cá hồi.\n2. **Về sản phẩm chăm sóc da:** Mình có **Xà phòng nghệ nhân Blackberry Sữa Dê** với thành phần tự nhiên, không chứa hóa chất độc hại, giúp dưỡng da rất tốt.\n\nBạn đang quan tâm cụ thể đến sản phẩm nào trong số này, hay muốn tìm kiếm một món đồ khác không ạ? Mời bạn cho mình biết thêm thông tin để mình hỗ trợ tốt nhất nhé!', '2026-07-12 21:31:49.000000', '[{\"product_id\":\"20\",\"url\":\"https://i.etsystatic.com/26202727/r/il/99fe09/5567543496/il_fullxfull.5567543496_bcnr.jpg\"},{\"product_id\":\"622\",\"url\":\"https://i.etsystatic.com/61582632/r/il/29773f/7556931202/il_510x638.7556931202_qjot.jpg\"},{\"product_id\":\"1486\",\"url\":\"https://i.etsystatic.com/39545350/r/il/217f89/6036497335/il_510x680.6036497335_6tdv.jpg\"}]', 'assistant', '9d276588-24ea-4ad8-99ec-3e4857a614f2', '9ae5e6ec-3d7b-452b-ac1a-ea01c1d05b31', b'0', NULL);
