INSERT INTO `chat_history` VALUES (358, 'Dạ, \"gét gô\" luôn ạ! Rất vui vì bạn đã sẵn sàng khám phá các sản phẩm tại cửa hàng Thu Ngân.\n\nHiện tại cửa hàng mình đang có một số sản phẩm rất thú vị, bạn có thể tham khảo qua nhé:\n\n1. **Tượng gốm táo gai điêu khắc bằng tay**: Một tác phẩm nghệ thuật độc đáo, được làm thủ công tỉ mỉ với lớp tráng men tinh tế, rất phù hợp để trang trí không gian sống. Giá là 1,953,000đ.\n2. **Bộ bát sứ ném quả lý gai**: Bộ 4 chiếc bát sứ cao cấp, an toàn khi dùng trong lò vi sóng và máy rửa chén. Sản phẩm này có giá 1,371,250đ.\n3. **Bộ ruồi câu cá Walt\'s Worm Jig**: Dành cho các tín đồ câu cá, đây là loại mồi giả Euro Nymphing cực kỳ hiệu quả, giá dao động từ 250,000đ đến 500,000đ tùy loại.\n\nBạn có muốn mình tư vấn kỹ hơn về món nào trong số này không, hay bạn đang tìm kiếm một sản phẩm cụ thể nào khác ạ?', '2026-07-12 23:05:48.000000', '[{\"product_id\":\"652\",\"url\":\"https://i.etsystatic.com/23120474/r/il/c01b0d/7137970722/il_510x638.7137970722_l6mq.jpg\"},{\"product_id\":\"1093\",\"url\":\"https://i.etsystatic.com/44733653/r/il/e30d0e/7616153180/il_510x680.7616153180_9qm5.jpg\"},{\"product_id\":\"20\",\"url\":\"https://i.etsystatic.com/26202727/r/il/99fe09/5567543496/il_fullxfull.5567543496_bcnr.jpg\"}]', 'assistant', 'f65ffe25-f62d-4ee5-b2df-26b032a1f995', '9ae5e6ec-3d7b-452b-ac1a-ea01c1d05b31', b'0', NULL);
