INSERT INTO `chat_history` VALUES (360, 'Dạ, \"gét gô\" luôn ạ! Có vẻ bạn đang rất quan tâm đến **Bộ bát sứ ném quả lý gai** đúng không ạ?\n\nTại cửa hàng Thu Ngân, mình hiện có 3 phiên bản của bộ bát sứ này với mức giá khác nhau để bạn lựa chọn tùy theo nhu cầu:\n\n1. **Bộ bát sứ ném quả lý gai (ID 1093)**: Giá 1,371,250đ.\n2. **Bộ bát sứ ném quả lý gai (ID 229)**: Giá 1,691,000đ.\n3. **Bộ bát sứ ném quả lý gai (ID 1957)**: Giá 2,565,750đ.\n\nCả 3 bộ đều là bộ 4 chiếc bát sứ cao cấp, dung tích 16oz mỗi bát, rất an toàn khi dùng trong lò vi sóng, máy rửa chén và lò nướng (lên đến 350°F). Điểm đặc biệt là lớp men phản ứng được làm thủ công nên mỗi bộ đều có những nét độc đáo riêng biệt.\n\nMời bạn xem hình ảnh sản phẩm bên dưới nhé. Bạn muốn mình tư vấn kỹ hơn về bộ nào không ạ?', '2026-07-12 23:06:04.000000', '[{\"product_id\":\"1093\",\"url\":\"https://i.etsystatic.com/44733653/r/il/e30d0e/7616153180/il_510x680.7616153180_9qm5.jpg\"},{\"product_id\":\"229\",\"url\":\"https://i.etsystatic.com/66562440/r/il/9b1bd0/8154793022/il_510x680.8154793022_25co.jpg\"},{\"product_id\":\"1957\",\"url\":\"https://i.etsystatic.com/39266300/r/il/80d571/7376413077/il_1588xN.7376413077_eoii.jpg\"}]', 'assistant', 'f65ffe25-f62d-4ee5-b2df-26b032a1f995', '9ae5e6ec-3d7b-452b-ac1a-ea01c1d05b31', b'0', NULL);
