INSERT INTO `chat_history` VALUES (362, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm tại cửa hàng Thu Ngân!\n\nSản phẩm có mã 2019 mà bạn đang tìm kiếm là **Kệ Gỗ Aurora Chạm Khắc Bằng Tay**. Đây là một chiếc kệ nổi được làm từ gỗ óc chó nguyên khối, các chi tiết cạnh được chạm khắc thủ công rất tinh xảo và được hoàn thiện bằng dầu sáp ong an toàn cho sức khỏe.\n\nThông tin chi tiết về sản phẩm:\n*   **Giá:** 3,487,750đ\n*   **Kích thước:** Chiều dài 24 inch, độ sâu 6 inch.\n*   **Đánh giá:** 5.0/5 sao.\n*   **Phụ kiện:** Đã bao gồm đầy đủ phần cứng để gắn kết kệ lên tường.\n\nMời bạn xem hình ảnh của sản phẩm bên dưới nhé! Nếu cần hỗ trợ thêm thông tin gì, bạn cứ nhắn mình nha.', '2026-07-12 23:06:43.000000', '[{\"product_id\":\"2019\",\"url\":\"https://i.etsystatic.com/58686080/r/il/58ce88/7278616766/il_1588xN.7278616766_dmln.jpg\"},{\"product_id\":\"2019\",\"url\":\"https://i.etsystatic.com/58686080/r/il/2e2bc4/7326536733/il_1588xN.7326536733_byc8.jpg\"},{\"product_id\":\"2019\",\"url\":\"https://i.etsystatic.com/58686080/r/il/b85710/7326536685/il_1588xN.7326536685_8prg.jpg\"}]', 'assistant', '3a8001df-6abc-404f-bf62-412e4470a059', '9ae5e6ec-3d7b-452b-ac1a-ea01c1d05b31', b'1', 'http://localhost:30000/product/2019');
