INSERT INTO `chat_messages` VALUES (20, 'Dưới đây là thông tin về các sản phẩm túi cầm tay (clutches) có sẵn:\n\n**1. Hand-Stitched Sweetgrass Leather Clutch**\n*   **Cửa hàng:** NettleNookStudio\n*   **Giá:** 100.5 USD\n*   **Mô tả:** Túi cầm tay da thủ công với chi tiết thêu tay sweetgrass. Da full-grain thuộc thảo mộc. Có túi khóa kéo bên trong, khóa nam châm. Kích thước: 9\"x5\". Kèm dây đeo cổ tay.\n*   **Chính sách:** Làm theo đơn 3-5 ngày làm việc. Miễn phí vận chuyển USPS First Class. Chấp nhận trả hàng trong 30 ngày. Gửi từ Asheville, NC.\n\n**2. Hand-Stitched Nettle Leather Clutch**\n*   **Cửa hàng:** RavenRidgeDesigns\n*   **Giá:** 87.01 USD\n*   **Mô tả:** Túi cầm tay da thủ công với chi tiết thêu tay nettle. Da full-grain thuộc thảo mộc. Có túi khóa kéo bên trong, khóa nam châm. Kích thước: 9\"x5\". Kèm dây đeo cổ tay.\n*   **Chính sách:** Thời gian xử lý 2-3 ngày. Miễn phí vận chuyển tiêu chuẩn. Tín dụng cửa hàng cho trả hàng trong 14 ngày. Gửi từ Taos, NM.\n\n**3. Hand-Stitched Trillium Leather Clutch**\n*   **Cửa hàng:** MapleBarkDesigns\n*   **Giá:** 117.86 USD\n*   **Mô tả:** Túi cầm tay da thủ công với chi tiết thêu tay trillium. Da full-grain thuộc thảo mộc. Có túi khóa kéo bên trong, khóa nam châm. Kích thước: 9\"x5\". Kèm dây đeo cổ tay.\n*   **Chính sách:** Thời gian chế tác 7-10 ngày. Miễn phí vận chuyển USPS Priority cho đơn hàng từ 75 USD trở lên. Đơn hàng tùy chỉnh không hoàn lại. Gửi từ Bozeman, MT.', '2026-04-13 05:41:14.000000', 'assistant', 'user-1766022973534', NULL, NULL);
INSERT INTO `chat_messages` VALUES (21, 'tôi muốn biết sản phẩm etsy', '2026-04-16 10:46:58.000000', 'user', 'user-1766022973534', '17e84f18-d093-472a-8689-fb067e572305', NULL);
INSERT INTO `chat_messages` VALUES (22, 'Chào bạn! Dựa trên dữ liệu sản phẩm Etsy mà tôi có, có vẻ như bạn đang quan tâm đến các sản phẩm tượng gốm sứ điêu khắc thủ công.\n\nDưới đây là một số sản phẩm tượng gốm sứ độc đáo mà bạn có thể tham khảo:\n\n1.  **Tượng gốm sứ Bloodroot điêu khắc thủ công (Hand-Sculpted Bloodroot Ceramic Figurine)**\n    *   **Mã sản phẩm:** 5000001815\n    *   **Cửa hàng:** EmeraldEweStudio\n    *   **Giá:** 59.3 USD\n    *   **Mô tả:** Tượng gốm sứ stoneware được điêu khắc thủ công với chi tiết men bloodroot. Mỗi sản phẩm đều được làm riêng lẻ và độc đáo, nung trong lò để đảm bảo độ bền. Cao khoảng 4 inch.\n    *   **Chính sách:** Sẵn sàng giao hàng ngay hôm nay, vận chuyển ưu tiên 7.95 USD, đổi trả dễ dàng trong 30 ngày. Gửi từ Burlington, VT.\n\n2.  **Tượng gốm sứ Rowan điêu khắc thủ công (Hand-Sculpted Rowan Ceramic Figurine)**\n    *   **Mã sản phẩm:** 5000001335\n    *   **Cửa hàng:** EmeraldEweStudio\n    *   **Giá:** 90.13 USD\n    *   **Mô tả:** Tượng gốm sứ stoneware được điêu khắc thủ công với chi tiết men rowan. Mỗi sản phẩm đều được làm riêng lẻ và độc đáo, nung trong lò để đảm bảo độ bền. Cao khoảng 4 inch.\n    *   **Chính sách:** Sẵn sàng giao hàng ngay hôm nay, vận chuyển ưu tiên 7.95 USD, đổi trả dễ dàng trong 30 ngày. Gửi từ Burlington, VT.\n\n3.  **Tượng gốm sứ Cattail điêu khắc thủ công (Hand-Sculpted Cattail Ceramic Figurine)**\n    *   **Mã sản phẩm:** 5000000343\n    *   **Cửa hàng:** CrimsonCloakCraft\n    *   **Giá:** 85.56 USD\n    *   **Mô tả:** Tượng gốm sứ stoneware được điêu khắc thủ công với chi tiết men cattail. Mỗi sản phẩm đều được làm riêng lẻ và độc đáo, nung trong lò để đảm bảo độ bền. Cao khoảng 4 inch.\n    *   **Chính sách:** Thường giao hàng vào ngày hôm sau, miễn phí vận chuyển cho tất cả các đơn hàng, đổi trả dễ dàng trong 30 ngày. Gửi từ Chattanooga, TN.\n\nTất cả các sản phẩm này đều thuộc danh mục \"Nghệ thuật & Đồ sưu tầm\" (Art & Collectibles) và \"Điêu khắc\" (Sculpture), là những tác phẩm thủ công độc đáo.\n\nBạn có muốn tìm hiểu thêm về một sản phẩm cụ thể nào không, hay có yêu cầu nào khác về sản phẩm Etsy không?', '2026-04-16 10:47:40.000000', 'assistant', 'user-1766022973534', '17e84f18-d093-472a-8689-fb067e572305', NULL);
INSERT INTO `chat_messages` VALUES (23, 'tôi muốn biết dây chuyền độc đáo', '2026-04-16 10:48:59.000000', 'user', 'user-1766022973534', '17e84f18-d093-472a-8689-fb067e572305', NULL);
INSERT INTO `chat_messages` VALUES (24, 'Chào bạn! Dựa trên yêu cầu của bạn về \"dây chuyền độc đáo\", tôi đã tìm thấy một sản phẩm rất đặc biệt mà bạn có thể quan tâm:\n\n**Dây chuyền mặt hình đường đua Circuit of the Americas (Circuit of the Americas Pendant Necklace Gold/Silver with Chain)**\n\n*   **Mã sản phẩm:** 1532044152\n*   **Cửa hàng:** TracksideJewelry\n*   **Giá:** 16.0 USD\n*   **Mô tả:** Đây là một chiếc dây chuyền mặt hình đường đua Circuit of the Americas (COTA) độc đáo, hoàn hảo để thể hiện niềm đam mê của bạn với thế giới đua xe tốc độ. Chiếc mặt dây chuyền được chế tác tinh xảo và tỉ mỉ, giống như đường đua COTA mang tính biểu tượng ở Austin, Texas.\n*   **Chính sách:** Đặt hàng hôm nay để nhận hàng vào khoảng 20-23 tháng 12. Chấp nhận đổi trả trong 30 ngày. Chi phí vận chuyển: 4.09 USD. Gửi từ New Baltimore, MI.\n*   **Danh mục:** Trang sức (Jewelry), Dây chuyền (Necklaces), Dây chuyền mặt (Pendant Necklaces).\n\nSản phẩm này chắc chắn sẽ là một món đồ trang sức độc đáo và ý nghĩa, đặc biệt nếu bạn hoặc người thân yêu có niềm yêu thích với đua xe!\n\nBạn có muốn tìm hiểu thêm về sản phẩm này hay có yêu cầu nào khác không?', '2026-04-16 10:49:04.000000', 'assistant', 'user-1766022973534', '17e84f18-d093-472a-8689-fb067e572305', NULL);
INSERT INTO `chat_messages` VALUES (25, 'còn sản phẩm dây chuyền nào khác không', '2026-04-16 10:49:30.000000', 'user', 'user-1766022973534', '17e84f18-d093-472a-8689-fb067e572305', NULL);
