INSERT INTO `chat_messages` VALUES (56, 'Chào bạn,\n\nDựa trên dữ liệu sản phẩm hiện có, tôi không tìm thấy sản phẩm \"giày da\" (leather shoes).\n\nTuy nhiên, tôi có một sản phẩm có sử dụng chất liệu da nhưng là một cuốn sổ tay:\n*   **Hand-Bound Heather Leather Journal** (Sổ tay bìa da Heather thủ công)\n    *   Mã sản phẩm (ID): 5000001244\n    *   Tên cửa hàng: DewdropDesignCo\n    *   Danh mục: Paper & Party, Stationery, Notebooks\n    *   Giá: **78.37 USD**\n    *   Mô tả: Sổ tay được đóng thủ công với bìa da màu heather và chỉ linen khâu Coptic. 200 trang giấy không axit 90gsm. Mở ra hoàn toàn phẳng. Kích thước A5 (5.8\"x8.3\").\n    *   Chính sách giao hàng và trả hàng: Được làm thủ công, thời gian chờ 7-10 ngày. Miễn phí vận chuyển USPS Priority cho đơn hàng từ 75 USD trở lên. Đơn hàng tùy chỉnh không được hoàn lại. Giao hàng từ Bozeman, MT.\n\nBạn có muốn tìm hiểu thêm về sản phẩm sổ tay này không, hoặc bạn có muốn tìm kiếm sản phẩm nào khác không?', '2026-06-25 08:21:37.000000', 'assistant', 'user-1766022973', 'aa7fb181-5b3b-44ab-841c-41ffb8bda176', NULL);
