INSERT INTO `chat_messages` VALUES (60, 'Chào bạn! Tôi là trợ lý ảo tư vấn sản phẩm Etsy và tôi không tìm thấy bất kỳ sản phẩm nào là \"iPhone 17\" hay các sản phẩm iPhone khác trong dữ liệu hiện có.\n\nCác sản phẩm tôi có thể giúp bạn tìm kiếm là các mặt hàng thủ công như:\n*   **Túi xách da cầm tay (clutch)**: \"Hand-Stitched Trillium Leather Clutch\" và \"Hand-Stitched Blackthorn Leather Clutch\".\n*   **Ba lô**: \"Waxed Canvas Quince Backpack\".\n\nBạn có muốn tìm hiểu thêm về các sản phẩm này không? Hoặc bạn có muốn tìm kiếm loại sản phẩm nào khác không?', '2026-06-25 08:22:23.000000', 'assistant', 'user-1766022973', '3c185ce4-527f-48b6-b6aa-a4612e2f8e53', NULL);
