INSERT INTO `chat_messages` VALUES (103, 'Chào bạn, tôi rất vui được cung cấp thêm thông tin chi tiết về **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã sản phẩm: 1155)** mà bạn đang quan tâm đây ạ:\n\n*   **Tên sản phẩm:** Kệ Gỗ Aurora Chạm Khắc Bằng Tay\n*   **Mã sản phẩm:** 1155\n*   **Giá:** 3,271,000đ\n*   **Mô tả:** Đây là một chiếc kệ nổi được làm từ gỗ óc chó nguyên khối, được chạm khắc thủ công tinh xảo với chi tiết cạnh cực quang độc đáo. Sản phẩm bao gồm tất cả các phần cứng cần thiết để gắn kết.\n    *   **Kích thước:** Chiều dài 24 inch (khoảng 61 cm), Độ sâu 6 inch (khoảng 15 cm).\n    *   **Chất liệu hoàn thiện:** Kệ được hoàn thiện bằng dầu sáp ong an toàn thực phẩm, đảm bảo độ bền và an toàn khi sử dụng.\n*   **Đánh giá:** Sản phẩm hiện có đánh giá 5.0/5 sao, tuy nhiên chưa có lượt bán nào.\n*   **Màu sắc & Kích thước:** Phiên bản này có màu sắc tiêu chuẩn và kích thước mặc định như mô tả trên.\n\nHy vọng thông tin này hữu ích cho bạn! Nếu bạn có bất kỳ câu hỏi nào khác hoặc muốn tìm hiểu thêm về các sản phẩm khác, đừng ngần ngại hỏi nhé.', '2026-06-25 10:37:41.000000', 'assistant', 'user-1766022973', '4c8c5e2f-4036-4e9c-a731-4b3dae33ac0f', NULL);
