INSERT INTO `chat_messages` VALUES (107, 'Chào bạn! Tôi đã tìm thấy thông tin về sản phẩm Kệ Gỗ Aurora mà bạn đang quan tâm.\n\nChúng tôi có sản phẩm **Kệ Gỗ Aurora Chạm Khắc Bằng Tay** với các tùy chọn sau, chủ yếu khác nhau về giá và mã sản phẩm:\n\n1.  **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã sản phẩm: 1155)**\n    *   **Giá:** 3,271,000đ\n    *   **Mô tả:** Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cực quang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.\n    *   **Đánh giá:** 5.0/5 (0 đã bán)\n\n2.  **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã sản phẩm: 291)**\n    *   **Giá:** 3,410,250đ\n    *   **Mô tả:** (Tương tự như trên) Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cực quang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.\n    *   **Đánh giá:** 5.0/5 (0 đã bán)\n\n3.  **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã sản phẩm: 2019)**\n    *   **Giá:** 3,487,750đ\n    *   **Mô tả:** (Tương tự như trên) Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cực quang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.\n    *   **Đánh giá:** 5.0/5 (1 đã bán)\n\nTất cả các phiên bản đều là kệ nổi được làm từ gỗ óc chó nguyên khối, chạm khắc thủ công tinh xảo, có kích thước dài 24 inch và sâu 6 inch, và được hoàn thiện bằng dầu sáp ong an toàn thực phẩm. Sản phẩm cũng đi kèm đầy đủ phần cứng để bạn dễ dàng lắp đặt.\n\nBạn có muốn tìm hiểu thêm về một phiên bản cụ thể nào không, hay có câu hỏi nào khác về sản phẩm này không ạ?', '2026-07-03 01:29:47.000000', 'assistant', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
