INSERT INTO `chat_messages` VALUES (111, 'Chào bạn! Rất vui được cung cấp thêm thông tin chi tiết về **Kệ Gỗ Aurora Chạm Khắc Bằng Tay** phiên bản đầu tiên mà bạn đã hỏi:\n\n**Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã sản phẩm: 1155)**\n\n*   **Giá:** 3,271,000đ\n*   **Mô tả chi tiết:** Đây là một chiếc kệ nổi được làm từ gỗ óc chó nguyên khối, được chạm khắc thủ công tinh xảo với chi tiết cạnh cực quang độc đáo. Sản phẩm đi kèm đầy đủ tất cả các phần cứng cần thiết để bạn dễ dàng gắn kết.\n*   **Kích thước:** Chiều dài 24 inch (khoảng 61 cm) và độ sâu 6 inch (khoảng 15 cm).\n*   **Hoàn thiện:** Bề mặt kệ được hoàn thiện bằng dầu sáp ong an toàn thực phẩm, đảm bảo độ bền và an toàn khi sử dụng.\n*   **Đánh giá:** Sản phẩm hiện có đánh giá 5.0/5 sao (dù chưa có lượt bán nào).\n\nBạn có muốn biết thêm về bất kỳ chi tiết nào khác của chiếc kệ này không ạ? Hoặc bạn có câu hỏi nào khác không?', '2026-07-03 01:31:17.000000', 'assistant', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
