INSERT INTO `chat_messages` VALUES (113, 'Chào bạn!\n\nTôi đã kiểm tra dữ liệu sản phẩm của cửa hàng, nhưng hiện tại tôi không tìm thấy sản phẩm **\"nhẫn kim cương\"** nào trong danh mục của chúng tôi.\n\nChúng tôi có một số mẫu nhẫn khác với pha lê hoặc tinh thể thô, ví dụ như:\n*   **Nhẫn tuyên bố quả việt quất pha lê thô**\n*   **Nhẫn tuyên bố Bloodroot tinh thể thô**\n*   **Nhẫn pha lê Damson thô**\n\nBạn có muốn tìm hiểu về các loại nhẫn này hoặc có quan tâm đến sản phẩm nào khác không ạ?', '2026-07-03 01:31:43.000000', 'assistant', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
