INSERT INTO `chat_messages` VALUES (115, 'Chào bạn! Rất vui được hỗ trợ bạn tìm kiếm sản phẩm nhẫn pha lê.\n\nChúng tôi có sản phẩm **Nhẫn pha lê Rowan thô** với các tùy chọn sau, chủ yếu khác nhau về giá và mã sản phẩm:\n\n1.  **Nhẫn pha lê Rowan thô (Mã sản phẩm: 1086)**\n    *   **Giá:** 1,151,250đ\n    *   **Mô tả:** Chiếc nhẫn nổi bật với pha lê thanh lương trà thô, được làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh, phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Sản phẩm được hoàn thiện với lớp vỏ thanh lương trà.\n    *   **Đánh giá:** 5.0/5 (0 đã bán)\n\n2.  **Nhẫn pha lê Rowan thô (Mã sản phẩm: 1950)**\n    *   **Giá:** 1,522,000đ\n    *   **Mô tả:** (Tương tự như trên) Chiếc nhẫn nổi bật với pha lê thanh lương trà thô, được làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh, phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Sản phẩm được hoàn thiện với lớp vỏ thanh lương trà.\n    *   **Đánh giá:** 5.0/5 (0 đã bán)\n\n3.  **Nhẫn pha lê Rowan thô (Mã sản phẩm: 222)**\n    *   **Giá:** 1,913,250đ\n    *   **Mô tả:** (Tương tự như trên) Chiếc nhẫn nổi bật với pha lê thanh lương trà thô, được làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh, phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Sản phẩm được hoàn thiện với lớp vỏ thanh lương trà.\n    *   **Đánh giá:** 5.0/5 (0 đã bán)\n\nTất cả các phiên bản đều là nhẫn nổi bật với pha lê thanh lương trà thô, làm từ đồng thau tái chế, có dây đeo điều chỉnh (kích cỡ 6-9) và mỗi tinh thể đều độc đáo.\n\nBạn có muốn tìm hiểu thêm về một phiên bản cụ thể nào không, hay có câu hỏi nào khác về sản phẩm này không ạ?', '2026-07-03 01:32:18.000000', 'assistant', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
INSERT INTO `chat_messages` VALUES (116, 'nhẫn thứ 3', '2026-07-03 01:32:29.000000', 'user', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
INSERT INTO `chat_messages` VALUES (117, 'Chào bạn! Rất vui được cung cấp thêm thông tin chi tiết về chiếc nhẫn pha lê thứ 3 mà bạn đang quan tâm:\n\nĐây là sản phẩm **Nhẫn pha lê Rowan thô (Mã sản phẩm: 222)**\n\n*   **Giá:** 1,913,250đ\n*   **Mô tả chi tiết:** Chiếc nhẫn này nổi bật với một viên pha lê thanh lương trà thô tự nhiên, mang vẻ đẹp độc đáo. Nhẫn được chế tác từ đồng thau tái chế, thân thiện với môi trường.\n*   **Kích thước:** Dây đeo của nhẫn có thể điều chỉnh linh hoạt, phù hợp với các kích cỡ từ 6 đến 9, giúp bạn dễ dàng điều chỉnh để vừa vặn nhất.\n*   **Đặc điểm nổi bật:** Mỗi tinh thể pha lê trên nhẫn đều là duy nhất về hình dạng và màu sắc, đảm bảo bạn sở hữu một món trang sức không trùng lặp. Sản phẩm được hoàn thiện với lớp vỏ thanh lương trà, tăng thêm vẻ đẹp tự nhiên.\n*   **Đánh giá:** Sản phẩm hiện có đánh giá 5.0/5 sao (dù chưa có lượt bán nào).\n\nBạn có muốn biết thêm về bất kỳ chi tiết nào khác của chiếc nhẫn này không ạ? Hoặc bạn có câu hỏi nào khác không?', '2026-07-03 01:32:34.000000', 'assistant', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
INSERT INTO `chat_messages` VALUES (118, 'ảnh của nhẫn thứ 3', '2026-07-03 01:32:41.000000', 'user', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
