INSERT INTO `chat_messages` VALUES (123, 'Chào bạn!\n\nRất vui được tiếp tục hỗ trợ bạn ạ.\n\nBạn có câu hỏi nào khác về sản phẩm nhẫn pha lê hay bất kỳ sản phẩm nào khác mà bạn đang quan tâm không? Tôi sẵn lòng cung cấp thêm thông tin chi tiết bằng văn bản ạ.', '2026-07-03 01:44:44.000000', 'assistant', 'user-1766022973', 'd2fa8cae-be85-4ee8-ba69-33be53cdfa32', NULL);
