INSERT INTO `chat_messages` VALUES (125, 'Chào bạn! Cửa hàng có một số mẫu nhẫn pha lê rất đẹp mà bạn có thể tham khảo đây ạ:\n\nChúng tôi có sản phẩm **Nhẫn pha lê Rowan thô**. Đây là những chiếc nhẫn nổi bật với pha lê thanh lương trà thô, được làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh linh hoạt, phù hợp với các kích cỡ từ 6-9. Mỗi tinh thể pha lê đều độc đáo về hình dạng và màu sắc, mang đến vẻ đẹp riêng biệt.\n\nHiện tại, mẫu nhẫn này có các mức giá khác nhau:\n*   **1,151,250đ** (Mã sản phẩm: 1086)\n*   **1,913,250đ** (Mã sản phẩm: 222)\n*   **1,522,000đ** (Mã sản phẩm: 1950)\n\nBạn có muốn xem chi tiết hơn về mẫu nào không ạ, hoặc bạn có câu hỏi gì khác về sản phẩm này không?', '2026-07-03 01:53:36.000000', 'assistant', 'user-1766022973', '100ddf27-74da-4cf5-9039-8d8cc95274b2', NULL);
