INSERT INTO `chat_messages` VALUES (128, 'Chào bạn! Rất vui được gặp bạn.\n\nBạn có cần tìm sản phẩm gì không ạ? Hãy cho tôi biết nếu bạn cần tư vấn về trang sức, đồ thể thao hay bất kỳ sản phẩm nào khác nhé!', '2026-07-04 14:08:54.000000', 'assistant', 'user-1766022973', 'f36c4e6b-4e28-4d15-8898-b0a5f809bccb', NULL);
