INSERT INTO `chat_messages` VALUES (130, 'Chào bạn! Tôi có tìm thấy một số mẫu nhẫn pha lê rất đẹp cho bạn đây ạ.\n\nChúng tôi có mẫu **Nhẫn pha lê Rowan thô** với các mức giá khác nhau để bạn lựa chọn:\n*   **Nhẫn pha lê Rowan thô** (Mã sản phẩm: 1086) - Giá: **1.151.250đ**\n*   **Nhẫn pha lê Rowan thô** (Mã sản phẩm: 1950) - Giá: **1.522.000đ**\n*   **Nhẫn pha lê Rowan thô** (Mã sản phẩm: 222) - Giá: **1.913.250đ**\n\nTất cả các mẫu nhẫn này đều nổi bật với pha lê thanh lương trà thô, được làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh linh hoạt, phù hợp với các kích cỡ từ 6-9. Đặc biệt, mỗi tinh thể pha lê đều có hình dạng và màu sắc độc đáo, mang đến vẻ đẹp riêng biệt cho từng chiếc nhẫn.\n\nBạn quan tâm đến mẫu nào hay muốn tìm hiểu thêm chi tiết về một chiếc nhẫn cụ thể không ạ?', '2026-07-04 14:09:08.000000', 'assistant', 'user-1766022973', 'f36c4e6b-4e28-4d15-8898-b0a5f809bccb', NULL);
INSERT INTO `chat_messages` VALUES (131, 'nhẫn id 1086', '2026-07-04 14:09:33.000000', 'user', 'user-1766022973', 'f36c4e6b-4e28-4d15-8898-b0a5f809bccb', NULL);
INSERT INTO `chat_messages` VALUES (132, 'Chào bạn! Tôi rất tiếc, nhưng hiện tại tôi không tìm thấy thông tin chi tiết về chiếc nhẫn có mã sản phẩm 1086 trong dữ liệu sản phẩm mà tôi đang có. Mặc dù tôi đã đề cập đến mẫu nhẫn này ở tin nhắn trước, có thể thông tin đã được cập nhật hoặc không còn hiển thị trong danh sách hiện tại.\n\nBạn có muốn tôi tìm kiếm lại các mẫu nhẫn pha lê khác hoặc bạn quan tâm đến một mã sản phẩm nào khác mà tôi đã liệt kê trước đó không ạ? Ví dụ như mã 1950 hoặc 222.', '2026-07-04 14:09:41.000000', 'assistant', 'user-1766022973', 'f36c4e6b-4e28-4d15-8898-b0a5f809bccb', NULL);
