INSERT INTO `chat_messages` VALUES (134, 'Chào bạn! Tôi xin lỗi vì sự nhầm lẫn ở tin nhắn trước. Cảm ơn bạn đã nhắc lại thông tin, tôi đã tìm thấy chi tiết về chiếc **Nhẫn pha lê Rowan thô** với mã sản phẩm **1086** đây ạ!\n\n**Thông tin chi tiết về Nhẫn pha lê Rowan thô (Mã sản phẩm: 1086):**\n*   **Giá:** **1.151.250đ**\n*   **Đánh giá:** 5.0/5 (hiện chưa có lượt bán)\n*   **Màu sắc:** Tiêu chuẩn\n*   **Kích thước:** Mặc định, dây đeo có thể điều chỉnh linh hoạt, phù hợp với các kích cỡ từ 6-9.\n*   **Mô tả:** Chiếc nhẫn này nổi bật với pha lê thanh lương trà thô, được làm từ đồng thau tái chế. Mỗi tinh thể pha lê đều có hình dạng và màu sắc độc đáo, mang đến vẻ đẹp riêng biệt cho từng chiếc nhẫn. Sản phẩm được hoàn thiện với lớp vỏ thanh lương trà.\n\nBạn có muốn tìm hiểu thêm về sản phẩm này hoặc có câu hỏi nào khác không ạ?', '2026-07-04 14:10:32.000000', 'assistant', 'user-1766022973', 'f36c4e6b-4e28-4d15-8898-b0a5f809bccb', NULL);
