INSERT INTO `chat_messages` VALUES (140, 'Chào bạn!\n\nTôi rất tiếc, tôi không tìm thấy chiếc nhẫn nào có mã sản phẩm chính xác là **\"1-86\"** trong dữ liệu sản phẩm của cửa hàng chúng ta.\n\nTuy nhiên, dựa trên lịch sử trò chuyện trước đó, bạn có đang muốn hỏi về chiếc **Nhẫn pha lê Rowan thô** với mã sản phẩm **1086** không ạ? Nếu đúng là mã 1086, tôi có thể cung cấp lại thông tin chi tiết cho bạn ngay bây giờ.\n\nBạn có thể vui lòng xác nhận lại mã sản phẩm bạn đang tìm kiếm không ạ?', '2026-07-04 14:11:32.000000', 'assistant', 'user-1766022973', 'f36c4e6b-4e28-4d15-8898-b0a5f809bccb', NULL);
INSERT INTO `chat_messages` VALUES (141, 'bạn có những sản phẩm gì', '2026-07-04 14:18:44.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (142, 'Chào bạn! Cửa hàng của chúng tôi hiện đang có các sản phẩm thuộc danh mục **Tắm & làm đẹp** rất được yêu thích.\n\nBạn có thể tham khảo một số sản phẩm nổi bật sau:\n\n*   **Xà phòng nghệ nhân Twilight Artisan sữa dê:** Đây là loại xà phòng sữa dê bổ dưỡng với hương thơm hoàng hôn và các thành phần thực vật tự nhiên. Sản phẩm được làm theo phương pháp xử lý lạnh giúp bảo quản glycerin tự nhiên, không chứa sunfat, paraben và màu nhân tạo.\n    *   Giá: Từ 381,000đ đến 444,250đ (tùy biến thể).\n*   **Tẩy tế bào chết toàn thân bằng đường Mugwort:** Sản phẩm tẩy tế bào chết toàn thân thủ công này được làm từ đường mía hữu cơ, tinh dầu ngải cứu và dầu dừa, giúp nhẹ nhàng tẩy tế bào chết và dưỡng ẩm cho da chỉ trong một bước.\n    *   Giá: 398,250đ.\n\nBạn quan tâm đến sản phẩm nào hay muốn tìm hiểu thêm về công dụng của chúng không?', '2026-07-04 14:18:47.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (143, 'còn sản phẩm nào khác khong', '2026-07-04 14:19:04.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (144, 'Chào bạn! Ngoài các sản phẩm Tắm & làm đẹp mà mình đã giới thiệu, cửa hàng chúng tôi còn có một số sản phẩm khác thuộc các danh mục đa dạng hơn nữa đấy ạ:\n\n**1. Danh mục Áo:**\n*   **Áo ăn cơm chưa:** Chiếc áo độc đáo với dòng chữ \"ăn cơm\" này hiện đang có ưu đãi cực lớn, giảm giá tới 90%! Từ 1,234,570đ nay chỉ còn **123,456đ**.\n\n**2. Danh mục Nhà cửa & cuộc sống:**\n*   **Thớt quả óc chó Rowan cuối hạt (Giá 4,200,750đ):** Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó thanh lương trà và cây phong. Sản phẩm nhẹ nhàng trên các cạnh dao, có rãnh nước ép ở một bên và được bôi bằng dầu khoáng an toàn thực phẩm. Kích thước dày 12\"x9\"x1,5\".\n*   **Thớt quả óc chó Rowan cuối hạt (Giá 2,891,500đ):** Tương tự, đây cũng là một chiếc thớt gỗ cứng thớ cuối thủ công chất lượng cao với các đặc điểm như trên. Kích thước dày 12\"x9\"x1,5\".\n\nBạn có muốn tìm hiểu thêm về sản phẩm nào trong số này không, hay bạn đang tìm kiếm một loại sản phẩm cụ thể nào đó ạ?', '2026-07-04 14:19:18.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (145, 'thớt quả hạt óc cho id mấy', '2026-07-04 14:20:21.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (146, 'Chào bạn! Đối với các sản phẩm thớt có thành phần quả óc chó, cửa hàng chúng tôi hiện có các mã sản phẩm (ID) sau đây ạ:\n\n*   **Thớt quả óc chó sầu riêng cuối hạt:** Có ID là **1988** (giá 2,332,000đ) và **260** (giá 3,568,250đ).\n*   **Thớt quả óc chó kế cuối hạt:** Có ID là **356** (giá 2,441,500đ).\n\nBạn có muốn tìm hiểu thêm chi tiết về sản phẩm nào không ạ?', '2026-07-04 14:20:32.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (147, 'thớt quả hạt óc chó id 260, ảnh và mô tả', '2026-07-04 14:21:05.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (148, 'Chào bạn! Mình rất vui được cung cấp thông tin chi tiết về sản phẩm **Thớt quả óc chó sầu riêng cuối hạt** có ID **260** mà bạn đang quan tâm ạ.\n\n**Mô tả sản phẩm:**\n*   **Tên sản phẩm:** Thớt quả óc chó sầu riêng cuối hạt\n*   **ID:** 260\n*   **Giá:** 3,568,250đ\n*   **Đánh giá:** 5.0/5 (hiện chưa có lượt bán)\n*   **Chi tiết:** Đây là chiếc thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó me chua và cây phong. Sản phẩm được thiết kế để nhẹ nhàng trên các cạnh dao, có rãnh nước ép tiện lợi ở một bên và được bôi bằng dầu khoáng an toàn thực phẩm. Kích thước của thớt là dày 12\"x9\"x1,5\".\n\nVề yêu cầu \"ảnh\" sản phẩm, rất tiếc là mình là trợ lý ảo nên không thể hiển thị hình ảnh trực tiếp cho bạn được. Tuy nhiên, bạn có thể truy cập website của cửa hàng hoặc liên hệ trực tiếp với chúng tôi để được xem hình ảnh sản phẩm này một cách rõ nét nhất nhé!\n\nBạn có muốn tìm hiểu thêm về sản phẩm này hay có câu hỏi nào khác không ạ?', '2026-07-04 14:21:10.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (149, 'còn ảnh nào khác không', '2026-07-04 14:21:25.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (150, 'Chào bạn! Mình hiểu là bạn đang hỏi về các sản phẩm khác mà bản thân chúng là \"ảnh\" (tức là các bản in ảnh nghệ thuật) phải không ạ?\n\nNếu đúng như vậy, cửa hàng chúng tôi có một số sản phẩm thuộc danh mục **Nghệ thuật & sưu tầm** là các bản in ảnh thiên nhiên rất đẹp và chất lượng cao đấy ạ:\n\n*   **Mỹ Thuật Lingonberry Chụp Ảnh Thiên Nhiên (ID: 557):** Đây là bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên lingonberry gốc, in trên giấy cotton 100% với mực màu, chống phai màu hơn 100 năm.\n    *   Giá: 806,500đ.\n*   **Mỹ Thuật In Ảnh Thiên Nhiên Bracken (ID: 1069):** Tương tự, đây là bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên dương xỉ nguyên bản, cũng được in trên giấy cotton 100% với mực màu và có độ bền màu cao.\n    *   Giá: 569,500đ.\n*   **Mỹ Thuật In Ảnh Thiên Nhiên Hoa Elderflower (ID: 813):** Sản phẩm này là bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa cơm cháy nguyên bản, với chất liệu và độ bền tương tự.\n    *   Giá: 744,500đ.\n\nCác sản phẩm này đều có sẵn ở nhiều kích thước khác nhau, từ 5x7 đến 16x20 inch.\n\nBạn có muốn mình cung cấp thêm thông tin chi tiết về bất kỳ bản in ảnh nghệ thuật nào trong số này không ạ?', '2026-07-04 14:21:31.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (151, 'ảnh của Thớt quả óc chó sầu riêng cuối hạt', '2026-07-04 14:21:49.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (152, 'Chào bạn! Mình hiểu là bạn đang muốn xem ảnh của sản phẩm **Thớt quả óc chó sầu riêng cuối hạt** ạ.\n\nNhư mình đã giải thích ở lần trước, rất tiếc là mình là trợ lý ảo nên không thể hiển thị hình ảnh trực tiếp cho bạn được.\n\nĐể xem hình ảnh của chiếc thớt này một cách rõ nét nhất, bạn có thể:\n*   Truy cập website chính thức của cửa hàng chúng tôi.\n*   Hoặc liên hệ trực tiếp với bộ phận chăm sóc khách hàng để được hỗ trợ gửi hình ảnh sản phẩm nhé.\n\nBạn có muốn mình cung cấp thêm thông tin chi tiết nào khác về sản phẩm này không ạ?', '2026-07-04 14:21:53.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (153, 'còn ảnh khác của nó không', '2026-07-04 14:22:12.000000', 'user', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
INSERT INTO `chat_messages` VALUES (154, 'Chào bạn! Mình hiểu là bạn vẫn đang muốn tìm kiếm các hình ảnh khác của sản phẩm **Thớt quả óc chó sầu riêng cuối hạt** ạ.\n\nMột lần nữa, mình xin lỗi vì không thể hiển thị trực tiếp bất kỳ hình ảnh nào của sản phẩm cho bạn được, dù là ảnh chính hay các ảnh góc cạnh khác. Là một trợ lý ảo, mình chỉ có thể cung cấp thông tin bằng văn bản thôi ạ.\n\nĐể có thể xem đầy đủ các hình ảnh của chiếc thớt này, bao gồm cả các góc chụp khác nhau (nếu có), bạn vui lòng:\n*   Truy cập vào website chính thức của cửa hàng chúng tôi.\n*   Hoặc liên hệ trực tiếp với bộ phận chăm sóc khách hàng để được hỗ trợ gửi hình ảnh sản phẩm một cách chi tiết nhất nhé.\n\nBạn có muốn mình cung cấp thêm thông tin mô tả nào khác về chiếc thớt này, hoặc bạn có câu hỏi nào khác về sản phẩm hay dịch vụ của cửa hàng không ạ?', '2026-07-04 14:22:16.000000', 'assistant', 'user-1766022973', 'faf4d97d-08e0-498b-be0b-609cbe0a2920', NULL);
