INSERT INTO `chat_messages` VALUES (176, 'Chào bạn,\n\nRất tiếc, tôi không tìm thấy sản phẩm \"áo in tên riêng\" nào trong danh mục của cửa hàng Thu Ngân hiện tại.\n\nCửa hàng chúng tôi có các sản phẩm áo như \"áo ăn cơm chưa\" (ID: 2030) hoặc các loại áo cơ bản khác. Bạn có muốn tham khảo không ạ?\n\nNgoài ra, cửa hàng Thu Ngân chuyên về túi xách, ví da, ba lô và các tác phẩm nghệ thuật. Nếu bạn quan tâm, tôi rất sẵn lòng giới thiệu thêm!', '2026-07-08 09:31:09.000000', 'assistant', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', '[{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"}]');
INSERT INTO `chat_messages` VALUES (177, 'giới thiệu về túi xách', '2026-07-08 09:31:26.000000', 'user', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', NULL);
INSERT INTO `chat_messages` VALUES (178, 'Chào bạn,\n\nRất vui được giới thiệu về các sản phẩm túi xách (ví cầm tay) của cửa hàng Thu Ngân ạ!\n\nCửa hàng chúng tôi có các mẫu ví cầm tay bằng da thủ công rất độc đáo và tinh tế, phù hợp cho những ai yêu thích sự tỉ mỉ và chất lượng cao.\n\nDưới đây là một số sản phẩm nổi bật:\n\n*   **Ly hợp da Sweetgrass khâu tay (ID: 201)**: Đây là ví cầm tay bằng da thủ công với chi tiết khâu tay sweetgrass độc đáo. Sản phẩm được làm từ da thuộc thực vật nguyên hạt, có túi khóa kéo bên trong và đóng mở bằng nam châm tiện lợi. Kích thước 9\"x5\" và bao gồm dây đeo cổ tay. Giá: **1,826,000đ**.\n*   **Ly hợp da Sweetgrass khâu tay (ID: 1065)**: Tương tự như sản phẩm trên, đây cũng là ví cầm tay bằng da thủ công với chi tiết khâu tay sweetgrass, làm từ da thuộc thực vật nguyên hạt, có túi khóa kéo bên trong và đóng mở bằng nam châm. Kích thước 9\"x5\" và bao gồm dây đeo cổ tay. Giá: **2,512,500đ**.\n*   **Ly Hợp Da Sloe Khâu Tay (ID: 169)**: Mẫu ví cầm tay bằng da này cũng có chi tiết khâu tay tinh xảo, được làm từ da thuộc thực vật nguyên hạt. Sản phẩm có túi khóa kéo bên trong, đóng mở bằng nam châm, kích thước 9\"x5\" và đi kèm dây đeo cổ tay. Giá: **3,168,750đ**.\n\nTất cả các sản phẩm này đều được đánh giá 5.0/5 sao và thể hiện sự khéo léo trong từng đường kim mũi chỉ.\n\nBạn có muốn xem thêm hình ảnh hoặc thông tin chi tiết về sản phẩm nào không ạ? Hoặc bạn đang tìm kiếm loại túi xách với kiểu dáng hay mức giá như thế nào?', '2026-07-08 09:31:33.000000', 'assistant', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', '[{\"product_id\":\"201\",\"url\":\"https://i.etsystatic.com/15558588/c/1503/1503/248/248/il/bc15d1/6907691644/il_510x680.6907691644_8a98.jpg\"},{\"product_id\":\"1065\",\"url\":\"https://i.etsystatic.com/56635429/r/il/0adb1b/7166336494/il_510x680.7166336494_a4t5.jpg\"},{\"product_id\":\"169\",\"url\":\"https://i.etsystatic.com/21508996/r/il/37bc7d/8041698649/il_1588xN.8041698649_7guv.jpg\"}]');
INSERT INTO `chat_messages` VALUES (179, '* **Ly hợp da Sweetgrass khâu tay (ID: 201)*, gửi thông tin chi tiết', '2026-07-08 09:31:53.000000', 'user', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', NULL);
INSERT INTO `chat_messages` VALUES (180, 'Chào bạn,\n\nTuyệt vời! Dưới đây là thông tin chi tiết về sản phẩm **Ly hợp da Sweetgrass khâu tay (ID: 201)** mà bạn quan tâm ạ:\n\n*   **Tên sản phẩm:** Ly hợp da Sweetgrass khâu tay\n*   **Mã sản phẩm (ID):** 201\n*   **Cửa hàng:** Thu Ngân\n*   **Danh mục:** Túi & ví (ví cầm tay)\n*   **Giá:** **1,826,000đ**\n*   **Đánh giá:** 5.0/5 sao (sản phẩm mới, chưa có lượt bán)\n*   **Màu sắc:** Tiêu chuẩn\n*   **Kích thước:** 9\"x5\" (khoảng 22.86cm x 12.7cm)\n*   **Mô tả chi tiết:** Đây là một chiếc ví cầm tay được làm thủ công tỉ mỉ từ da thuộc thực vật nguyên hạt, nổi bật với chi tiết khâu tay sweetgrass độc đáo. Bên trong ví có một túi khóa kéo tiện lợi để bạn cất giữ những vật dụng nhỏ. Ví được đóng mở bằng nam châm, rất dễ sử dụng và an toàn. Sản phẩm còn đi kèm dây đeo cổ tay, giúp bạn dễ dàng mang theo.\n\nĐây là một lựa chọn tuyệt vời cho những ai yêu thích sự tinh tế, chất lượng da thật và phong cách thủ công độc đáo.\n\nBạn có muốn xem thêm hình ảnh của sản phẩm này không, hoặc có câu hỏi nào khác về chiếc ví này không ạ?', '2026-07-08 09:31:58.000000', 'assistant', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', '[{\"product_id\":\"201\",\"url\":\"https://i.etsystatic.com/15558588/c/1503/1503/248/248/il/bc15d1/6907691644/il_510x680.6907691644_8a98.jpg\"},{\"product_id\":\"1065\",\"url\":\"https://i.etsystatic.com/56635429/r/il/0adb1b/7166336494/il_510x680.7166336494_a4t5.jpg\"},{\"product_id\":\"1929\",\"url\":\"https://i.etsystatic.com/62556546/r/il/d4f1b3/7665969534/il_510x680.7665969534_7o76.jpg\"}]');
INSERT INTO `chat_messages` VALUES (181, 'ảnh của sản phẩm id 201', '2026-07-08 09:32:17.000000', 'user', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', NULL);
INSERT INTO `chat_messages` VALUES (182, 'Chào bạn,\n\nRất tiếc, tôi không thể hiển thị trực tiếp hình ảnh của sản phẩm **Ly hợp da Sweetgrass khâu tay (ID: 201)** trong cuộc trò chuyện này.\n\nLà một trợ lý ảo, tôi chỉ có thể cung cấp thông tin mô tả bằng văn bản. Tuy nhiên, tôi có thể khẳng định rằng sản phẩm này được làm thủ công tỉ mỉ với chi tiết khâu tay sweetgrass độc đáo và chất liệu da thuộc thực vật nguyên hạt cao cấp.\n\nBạn có muốn tôi mô tả thêm về kiểu dáng, màu sắc hoặc bất kỳ chi tiết nào khác của chiếc ví này không ạ? Hoặc bạn có câu hỏi nào khác về sản phẩm này không?', '2026-07-08 09:32:19.000000', 'assistant', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', '[{\"product_id\":\"1901\",\"url\":\"https://i.etsystatic.com/58081149/r/il/62f0eb/8122398351/il_510x680.8122398351_527c.jpg\"},{\"product_id\":\"205\",\"url\":\"https://i.etsystatic.com/27194634/r/il/2166a7/7936821260/il_510x680.7936821260_nvzd.jpg\"}]');
INSERT INTO `chat_messages` VALUES (183, 'nhẫn pha lê thô', '2026-07-08 09:33:34.000000', 'user', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', NULL);
INSERT INTO `chat_messages` VALUES (184, 'Chào bạn,\n\nRất vui được giới thiệu các mẫu nhẫn pha lê thô tại cửa hàng Thu Ngân ạ! Chúng tôi có một số lựa chọn độc đáo trong danh mục trang sức.\n\nDưới đây là các sản phẩm nhẫn pha lê thô mà bạn có thể tham khảo:\n\n*   **Nhẫn pha lê thô (ID: 1502)**:\n    *   **Giá:** **1,581,250đ**\n    *   **Mô tả:** Chiếc nhẫn nổi bật với pha lê màu me chua thô, được làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh, phù hợp với kích cỡ 6-9. Mỗi tinh thể đều độc đáo về hình dạng và màu sắc, hoàn thiện với lớp patina cây me chua.\n    *   **Đánh giá:** 5.0/5 sao (sản phẩm mới, chưa có lượt bán).\n\n*   **Nhẫn pha lê thô (ID: 638)**:\n    *   **Giá:** **939,250đ**\n    *   **Mô tả:** Tương tự như sản phẩm trên, đây cũng là chiếc nhẫn có pha lê màu me chua thô, làm từ đồng thau tái chế. Dây đeo có thể điều chỉnh (kích cỡ 6-9). Mỗi tinh thể là duy nhất và được hoàn thiện với lớp patina cây me chua.\n    *   **Đánh giá:** 5.0/5 sao (sản phẩm mới, chưa có lượt bán).\n\nNgoài ra, chúng tôi còn có một mẫu nhẫn pha lê thô khác với tên gọi hơi khác một chút:\n\n*   **Nhẫn pha lê Rowan thô (ID: 1950)**:\n    *   **Giá:** **1,522,000đ**\n    *   **Mô tả:** Chiếc nhẫn này nổi bật với pha lê thanh lương trà thô, được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh, phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc, hoàn thiện với lớp vỏ thanh lương trà.\n    *   **Đánh giá:** 5.0/5 sao (sản phẩm mới, chưa có lượt bán).\n\nBạn có muốn tôi cung cấp thêm thông tin chi tiết về mẫu nhẫn nào không ạ? Hoặc bạn có câu hỏi nào khác về các sản phẩm này không?', '2026-07-08 09:33:40.000000', 'assistant', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', '[{\"product_id\":\"1502\",\"url\":\"https://i.etsystatic.com/62945139/c/875/875/74/74/il/4a74f5/7583190077/il_510x680.7583190077_761c.jpg\"},{\"product_id\":\"638\",\"url\":\"https://i.etsystatic.com/18856089/r/il/c5f1f7/7225818892/il_510x638.7225818892_aq4a.jpg\"},{\"product_id\":\"1950\",\"url\":\"https://i.etsystatic.com/19828721/r/il/fea32e/6452769971/il_1588xN.6452769971_o2k0.jpg\"}]');
INSERT INTO `chat_messages` VALUES (185, 'thông tin chi tiết về sản phẩm id 1950', '2026-07-08 09:34:05.000000', 'user', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', NULL);
INSERT INTO `chat_messages` VALUES (186, 'Chào bạn,\n\nTuyệt vời! Dưới đây là thông tin chi tiết về sản phẩm **Nhẫn pha lê Rowan thô (ID: 1950)** mà bạn quan tâm ạ:\n\n*   **Tên sản phẩm:** Nhẫn pha lê Rowan thô\n*   **Mã sản phẩm (ID):** 1950\n*   **Cửa hàng:** Thu Ngân\n*   **Danh mục:** Trang sức\n*   **Giá:** **1,522,000đ**\n*   **Đánh giá:** 5.0/5 sao (sản phẩm mới, chưa có lượt bán)\n*   **Màu sắc:** Tiêu chuẩn\n*   **Kích thước:** Dây đeo có thể điều chỉnh, phù hợp với kích cỡ 6-9.\n*   **Mô tả chi tiết:** Chiếc nhẫn này nổi bật với một viên pha lê thanh lương trà (Rowan) thô, mang vẻ đẹp tự nhiên và độc đáo. Nhẫn được làm từ đồng thau tái chế, thân thiện với môi trường. Dây đeo có thể điều chỉnh linh hoạt, giúp bạn dễ dàng điều chỉnh để vừa vặn với ngón tay có kích cỡ từ 6 đến 9. Mỗi tinh thể pha lê đều là duy nhất về hình dạng và màu sắc, đảm bảo bạn sở hữu một món trang sức không trùng lặp. Sản phẩm được hoàn thiện với lớp vỏ thanh lương trà đặc trưng, tạo nên vẻ ngoài mộc mạc và tinh tế.\n\nĐây là một lựa chọn tuyệt vời cho những ai yêu thích trang sức độc đáo, mang đậm dấu ấn thiên nhiên và phong cách thủ công.\n\nBạn có muốn xem thêm hình ảnh (nếu có thể) hoặc có câu hỏi nào khác về chiếc nhẫn này không ạ?', '2026-07-08 09:34:10.000000', 'assistant', 'user-1766022973', '99433f9e-5fcc-40e5-894e-5434bd50e02e', '[{\"product_id\":\"1950\",\"url\":\"https://i.etsystatic.com/19828721/r/il/fea32e/6452769971/il_1588xN.6452769971_o2k0.jpg\"},{\"product_id\":\"1967\",\"url\":\"https://i.etsystatic.com/11339550/r/il/60d3e3/6564310397/il_1588xN.6564310397_jm4x.jpg\"},{\"product_id\":\"497\",\"url\":\"https://i.etsystatic.com/28419701/r/il/631041/7763671654/il_510x638.7763671654_5eyy.jpg\"}]');
INSERT INTO `chat_messages` VALUES (187, 'kệ gỗ aurora', '2026-07-08 09:36:12.000000', 'user', 'user-1766022973', '1fd90817-57a1-4487-86c2-d5840b83e4c1', NULL);
INSERT INTO `chat_messages` VALUES (188, 'Chào bạn, cảm ơn bạn đã quan tâm đến sản phẩm của cửa hàng Thu Ngân!\n\nHiện tại, chúng tôi có sản phẩm **Kệ Gỗ Aurora Chạm Khắc Bằng Tay** rất đẹp và độc đáo. Đây là kệ nổi được làm từ gỗ óc chó nguyên khối, chạm khắc thủ công với chi tiết cạnh cực quang tinh xảo. Kệ có chiều dài 24 inch (khoảng 61 cm) và độ sâu 6 inch (khoảng 15 cm), được hoàn thiện bằng dầu sáp ong an toàn thực phẩm và bao gồm đầy đủ các phần cứng để gắn kết.\n\nSản phẩm này có các mức giá khác nhau tùy theo mã sản phẩm:\n*   **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã ID: 1155)** có giá **3,271,000đ**.\n*   **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã ID: 291)** có giá **3,410,250đ**.\n*   **Kệ Gỗ Aurora Chạm Khắc Bằng Tay (Mã ID: 2019)** có giá **3,487,750đ** và đã có 1 sản phẩm được bán ra với đánh giá 5.0/5.\n\nBạn có muốn tìm hiểu thêm về mã sản phẩm cụ thể nào không ạ, hoặc có câu hỏi nào khác về sản phẩm này không?', '2026-07-08 09:36:17.000000', 'assistant', 'user-1766022973', '1fd90817-57a1-4487-86c2-d5840b83e4c1', '[{\"product_id\":\"291\",\"url\":\"https://i.etsystatic.com/65228819/r/il/16fd6b/8190016837/il_510x680.8190016837_5vfq.jpg\"},{\"product_id\":\"2019\",\"url\":\"https://i.etsystatic.com/58686080/r/il/58ce88/7278616766/il_1588xN.7278616766_dmln.jpg\"},{\"product_id\":\"1155\",\"url\":\"https://i.etsystatic.com/66490104/r/il/8bed8d/8202670889/il_510x680.8202670889_agmx.jpg\"}]');
INSERT INTO `chat_messages` VALUES (189, 'thông tin snar phẩm 1155', '2026-07-08 09:36:39.000000', 'user', 'user-1766022973', '1fd90817-57a1-4487-86c2-d5840b83e4c1', NULL);
INSERT INTO `chat_messages` VALUES (190, 'Chào bạn,\n\nBạn đang muốn tìm hiểu thêm về sản phẩm có mã ID 1155.\n\nDựa trên dữ liệu sản phẩm hiện có, tôi không tìm thấy thêm thông tin chi tiết cụ thể nào khác cho mã sản phẩm **1155** ngoài những gì chúng ta đã trao đổi.\n\nTuy nhiên, tôi có thể nhắc lại thông tin chung về sản phẩm **Kệ Gỗ Aurora Chạm Khắc Bằng Tay** mà mã 1155 thuộc về:\n*   Đây là một chiếc kệ nổi được làm từ gỗ óc chó nguyên khối, được chạm khắc thủ công với chi tiết cạnh cực quang tinh xảo.\n*   Kệ có chiều dài 24 inch (khoảng 61 cm) và độ sâu 6 inch (khoảng 15 cm).\n*   Sản phẩm được hoàn thiện bằng dầu sáp ong an toàn thực phẩm và bao gồm đầy đủ các phần cứng để gắn kết.\n*   Mã sản phẩm **1155** có giá là **3,271,000đ**.\n\nBạn có muốn tôi tìm kiếm sản phẩm khác hoặc có câu hỏi nào khác không ạ?', '2026-07-08 09:36:47.000000', 'assistant', 'user-1766022973', '1fd90817-57a1-4487-86c2-d5840b83e4c1', '[{\"product_id\":\"1054\",\"url\":\"https://i.etsystatic.com/63337382/r/il/0b15c9/7688670671/il_510x680.7688670671_p0mb.jpg\"},{\"product_id\":\"574\",\"url\":\"https://i.etsystatic.com/17527925/r/il/44f718/7759255025/il_510x638.7759255025_l9aw.jpg\"},{\"product_id\":\"925\",\"url\":\"https://i.etsystatic.com/10204022/r/il/2db12b/8192605987/il_510x680.8192605987_ozpj.jpg\"}]');
INSERT INTO `chat_messages` VALUES (191, 'ID 1155', '2026-07-08 09:37:05.000000', 'user', 'user-1766022973', '1fd90817-57a1-4487-86c2-d5840b83e4c1', NULL);
