INSERT INTO `chat_messages` VALUES (194, 'Chào bạn, tôi là trợ lý ảo tư vấn sản phẩm của cửa hàng. Rất tiếc, tôi không có thông tin về thời tiết hôm nay.\n\nBạn có muốn tìm hiểu về các sản phẩm của cửa hàng không ạ? Tôi có thể giúp bạn tìm kiếm thông tin về áo hoặc các sản phẩm nghệ thuật và sưu tầm.', '2026-07-08 09:43:29.000000', 'assistant', 'user-1766022973', 'deac9b74-ceca-412e-8539-2f473d8c234c', '[{\"product_id\":\"77\",\"url\":\"https://i.etsystatic.com/63125473/r/il/1372af/8016911479/il_1588xN.8016911479_8coj.jpg\"},{\"product_id\":\"1805\",\"url\":\"https://i.etsystatic.com/9487154/c/1700/1700/399/166/il/e14cc6/4280898027/il_510x680.4280898027_oqj8.jpg\"}]');
