INSERT INTO `chat_messages` VALUES (196, 'Chào bạn, rất vui được giới thiệu các sản phẩm về áo của cửa hàng Thu Ngân ạ. Hiện tại, chúng tôi có hai mẫu áo sau đây:\n\n1.  **Áo (Mã sản phẩm: 2021)**:\n    *   Giá: 123,000đ\n    *   Mô tả: Đây là một mẫu áo cơ bản, dễ mặc ạ.\n\n2.  **Áo ăn cơm chưa (Mã sản phẩm: 2030)**:\n    *   Giá ưu đãi: Chỉ còn 123,456đ (đã giảm 90% so với giá gốc 1,234,570đ!)\n    *   Mô tả: Mẫu áo này có in chữ \"ăn cơm\" rất độc đáo và cá tính ạ.\n\nBạn quan tâm đến sản phẩm nào hay muốn xem thêm chi tiết không ạ?', '2026-07-08 09:43:50.000000', 'assistant', 'user-1766022973', 'deac9b74-ceca-412e-8539-2f473d8c234c', '[{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"}]');
