INSERT INTO `chat_messages` VALUES (198, 'Chào bạn, bạn muốn tìm hiểu thêm về sản phẩm **Áo (Mã 2021)** hay **Áo ăn cơm chưa (Mã 2030)** ạ?\n\nNếu bạn quan tâm đến **Áo (Mã sản phẩm: 2021)**, đây là thông tin chi tiết ạ:\n*   **Tên sản phẩm:** Áo\n*   **Mã sản phẩm:** 2021\n*   **Cửa hàng:** Thu Ngân\n*   **Danh mục:** Áo\n*   **Giá:** 123,000đ\n*   **Mô tả:** Đây là một mẫu áo cơ bản, dễ mặc ạ.\n*   **Đánh giá:** Sản phẩm hiện chưa có đánh giá và chưa có lượt bán nào ạ.\n\nMời bạn xem ảnh sản phẩm Áo (Mã 2021) bên dưới nhé.\n\nBạn có muốn tôi cung cấp thêm thông tin về **Áo ăn cơm chưa (Mã sản phẩm: 2030)** không ạ?', '2026-07-08 09:44:41.000000', 'assistant', 'user-1766022973', 'deac9b74-ceca-412e-8539-2f473d8c234c', '[{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"}]');
