INSERT INTO `chat_messages` VALUES (202, 'Chào bạn, bạn đang tìm giày da vẽ tay độc lạ phải không ạ?\n\nCửa hàng Pikachu có mẫu **Giày da vẽ tay hoa văn độc lạ (Mã sản phẩm: 2032)** rất phù hợp với yêu cầu của bạn đó ạ!\n\nSản phẩm này đang có chương trình giảm giá đặc biệt: từ 579,000đ nay chỉ còn **500,000đ**, giảm tới 14%. Giày được làm từ chất liệu cao cấp, đảm bảo sự thoải mái và bền đẹp.\n\nMời bạn xem hình ảnh sản phẩm bên dưới nhé!', '2026-07-08 09:45:48.000000', 'assistant', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', '[{\"product_id\":\"2032\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1782311376/zvoglzm219pu1eejut0s.png\"}]');
INSERT INTO `chat_messages` VALUES (203, 'kệ gỗ aurora', '2026-07-08 09:46:05.000000', 'user', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', NULL);
INSERT INTO `chat_messages` VALUES (204, 'Chào bạn, bạn đang tìm kệ gỗ Aurora phải không ạ?\n\nCửa hàng Thu Ngân có mẫu **Kệ Gỗ Aurora Chạm Khắc Bằng Tay** rất độc đáo và tinh xảo đó ạ!\n\nSản phẩm này được làm từ gỗ óc chó nguyên khối, chạm khắc thủ công với chi tiết cạnh cực quang, mang lại vẻ đẹp sang trọng cho không gian nhà bạn. Kệ có chiều dài 24 inch và độ sâu 6 inch, hoàn thiện bằng dầu sáp ong an toàn thực phẩm.\n\nHiện tại, mẫu kệ này có các mức giá khác nhau tùy theo mã sản phẩm, dao động từ **3,271,000đ** đến **3,487,750đ**.\n\nMời bạn xem hình ảnh của sản phẩm Kệ Gỗ Aurora Chạm Khắc Bằng Tay bên dưới nhé!', '2026-07-08 09:46:11.000000', 'assistant', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', '[{\"product_id\":\"291\",\"url\":\"https://i.etsystatic.com/65228819/r/il/16fd6b/8190016837/il_510x680.8190016837_5vfq.jpg\"},{\"product_id\":\"2019\",\"url\":\"https://i.etsystatic.com/58686080/r/il/58ce88/7278616766/il_1588xN.7278616766_dmln.jpg\"},{\"product_id\":\"1155\",\"url\":\"https://i.etsystatic.com/66490104/r/il/8bed8d/8202670889/il_510x680.8202670889_agmx.jpg\"}]');
