INSERT INTO `chat_messages` VALUES (206, 'Chào bạn, rất xin lỗi nếu bạn chưa thấy hình ảnh ạ. Theo quy định của hệ thống, hình ảnh của sản phẩm **Áo ăn cơm chưa (Mã 2030)** sẽ được hiển thị ngay bên dưới câu trả lời này. Mời bạn xem lại nhé.\n\nBạn có muốn tôi cung cấp thêm thông tin gì về sản phẩm này hay sản phẩm khác không ạ?', '2026-07-08 09:46:30.000000', 'assistant', 'user-1766022973', 'deac9b74-ceca-412e-8539-2f473d8c234c', '[{\"product_id\":\"2030\",\"url\":\"https://res.cloudinary.com/dqghfi8be/image/upload/v1781768428/jmcbufrn0c5etuyxnqbc.jpg\"}]');
INSERT INTO `chat_messages` VALUES (207, 'còn hình ảnh nào khác của sản phẩm kệ gỗ không', '2026-07-08 09:46:53.000000', 'user', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', NULL);
INSERT INTO `chat_messages` VALUES (208, 'Chào bạn, hiện tại mình chỉ có một hình ảnh chính của mẫu Kệ Gỗ Aurora Chạm Khắc Bằng Tay để hiển thị thôi ạ.\n\nTuy nhiên, cửa hàng Thu Ngân còn có một số mẫu kệ gỗ chạm khắc thủ công khác với thiết kế độc đáo không kém, bạn có muốn tham khảo không ạ?\n\nVí dụ, có mẫu **Kệ gỗ hình giọt nước tuyết chạm khắc thủ công** được làm từ gỗ óc chó nguyên khối với chi tiết cạnh hình giọt nước tuyết tinh xảo. Sản phẩm này có giá từ **1,752,000đ**.\n\nHoặc mẫu **Kệ Gỗ Sloe Chạm Khắc Bằng Tay** cũng từ gỗ óc chó nguyên khối, chạm khắc thủ công với chi tiết cạnh dốc độc đáo, có giá **2,720,500đ**.\n\nMời bạn xem hình ảnh của các sản phẩm này bên dưới nhé!', '2026-07-08 09:47:02.000000', 'assistant', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', '[{\"product_id\":\"483\",\"url\":\"https://i.etsystatic.com/63483226/r/il/1a2825/8036679678/il_510x638.8036679678_lgx0.jpg\"},{\"product_id\":\"1347\",\"url\":\"https://i.etsystatic.com/66490104/r/il/d1ab5a/8194772821/il_510x680.8194772821_axyv.jpg\"},{\"product_id\":\"547\",\"url\":\"https://i.etsystatic.com/65309691/r/il/bc2fcf/7925116497/il_510x638.7925116497_gyqr.jpg\"}]');
INSERT INTO `chat_messages` VALUES (209, 'cho tôi thông tin của kệ giọt nước', '2026-07-08 09:47:38.000000', 'user', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', NULL);
INSERT INTO `chat_messages` VALUES (210, 'Chào bạn, bạn đang muốn tìm hiểu thêm về mẫu **Kệ gỗ hình giọt nước tuyết chạm khắc thủ công** phải không ạ?\n\nĐây là một sản phẩm rất tinh xảo từ cửa hàng Thu Ngân đó ạ!\n\nKệ được làm từ gỗ óc chó nguyên khối, chạm khắc thủ công với chi tiết cạnh hình giọt nước tuyết độc đáo. Sản phẩm này không chỉ là một chiếc kệ mà còn là một tác phẩm nghệ thuật, mang lại vẻ đẹp sang trọng và tinh tế cho không gian của bạn.\n\nKệ có chiều dài 24 inch và độ sâu 6 inch, đi kèm đầy đủ các phần cứng để bạn dễ dàng lắp đặt. Bề mặt kệ được hoàn thiện bằng dầu sáp ong an toàn thực phẩm, đảm bảo độ bền và an toàn khi sử dụng.\n\nHiện tại, mẫu kệ này có hai mức giá khác nhau tùy theo mã sản phẩm:\n*   **1,752,000đ** (Mã sản phẩm: 483)\n*   **2,535,750đ** (Mã sản phẩm: 1347)\n\nMời bạn xem hình ảnh của sản phẩm Kệ gỗ hình giọt nước tuyết chạm khắc thủ công bên dưới nhé!', '2026-07-08 09:47:43.000000', 'assistant', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', '[{\"product_id\":\"483\",\"url\":\"https://i.etsystatic.com/63483226/r/il/1a2825/8036679678/il_510x638.8036679678_lgx0.jpg\"},{\"product_id\":\"1347\",\"url\":\"https://i.etsystatic.com/66490104/r/il/d1ab5a/8194772821/il_510x680.8194772821_axyv.jpg\"},{\"product_id\":\"429\",\"url\":\"https://i.etsystatic.com/57359982/r/il/f390f2/6705902668/il_510x638.6705902668_7mks.jpg\"}]');
INSERT INTO `chat_messages` VALUES (211, 'cho tôi thông tin kỹ hơn của sản phẩm 483', '2026-07-08 09:49:50.000000', 'user', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', NULL);
INSERT INTO `chat_messages` VALUES (212, 'Chào bạn, bạn muốn tìm hiểu thông tin chi tiết hơn về mẫu **Kệ gỗ hình giọt nước tuyết chạm khắc thủ công (Mã sản phẩm: 483)** phải không ạ?\n\nĐây là một sản phẩm rất đặc biệt từ cửa hàng Thu Ngân đó ạ!\n\n*   **Chất liệu:** Kệ được làm từ gỗ óc chó nguyên khối cao cấp, đảm bảo độ bền và vẻ đẹp tự nhiên.\n*   **Thiết kế:** Sản phẩm được chạm khắc thủ công tỉ mỉ với chi tiết cạnh hình giọt nước tuyết độc đáo, mang lại vẻ đẹp tinh xảo và sang trọng cho không gian của bạn.\n*   **Kích thước:** Kệ có chiều dài 24 inch (khoảng 61 cm) và độ sâu 6 inch (khoảng 15 cm), kích thước tiêu chuẩn phù hợp với nhiều không gian.\n*   **Hoàn thiện:** Bề mặt kệ được hoàn thiện bằng dầu sáp ong an toàn thực phẩm, giúp bảo vệ gỗ và an toàn khi sử dụng.\n*   **Lắp đặt:** Sản phẩm bao gồm đầy đủ tất cả các phần cứng gắn kết, giúp bạn dễ dàng lắp đặt tại nhà.\n*   **Giá:** Mẫu kệ này có giá **1,752,000đ**.\n*   **Đánh giá:** Sản phẩm hiện đang có đánh giá 5.0/5 sao.\n\nMời bạn xem hình ảnh của sản phẩm Kệ gỗ hình giọt nước tuyết chạm khắc thủ công (Mã sản phẩm: 483) bên dưới nhé!', '2026-07-08 09:49:55.000000', 'assistant', 'user-1766022973', 'cee950d6-b805-4abc-9ff3-5898f114d54e', '[{\"product_id\":\"483\",\"url\":\"https://i.etsystatic.com/63483226/r/il/1a2825/8036679678/il_510x638.8036679678_lgx0.jpg\"}]');
